    'list_this_environment_s_webhook_endpoints_where_they_po_50897ffc' => 'Wyświetlanie punktów końcowych webhooków tego środowiska: adresów docelowych, subskrybowanych zdarzeń i stanu wstrzymania — nigdy sekretów podpisujących.',
    'list_the_hooks_called_during_sign_in_and_token_issuance_563aad82' => 'Wyświetlanie hooków wywoływanych podczas logowania i wydawania tokenów oraz informacji, czy są aktywne.',
    'list_the_siem_destinations_this_environment_s_audit_tra_fe43c8df' => 'Wyświetlanie miejsc docelowych SIEM, do których przesyłany jest dziennik audytu tego środowiska, oraz informacji, czy są włączone.',
    'read_this_environment_s_domain_events_the_same_events_w_a994d958' => 'Odczytywanie zdarzeń domenowych tego środowiska — tych samych, które dostarczają webhooki — za pomocą kursora.',
    'read_this_environment_s_audit_trail_who_did_what_to_wha_3e0d9fc8' => 'Odczytywanie dziennika audytu tego środowiska: kto, co, na jakim zasobie i kiedy zrobił.',
    'register_repoint_pause_resume_re_key_and_delete_webhook_59f2b3cf' => 'Rejestrowanie punktów końcowych webhooków, zmiana ich adresów, wstrzymywanie, wznawianie, wymiana kluczy i usuwanie. Nowy lub wymieniony sekret podpisujący jest wyświetlany tylko raz.',
    'register_pause_activate_and_remove_hooks_endpoints_that_17dc8c62' => 'Rejestrowanie, wstrzymywanie, aktywowanie i usuwanie hooków — punktów końcowych, które mogą dodawać deklaracje do tokenów lub odrzucać logowanie.',
    'create_disable_resume_and_delete_audit_log_streams_a_ge_d507a36c' => 'Tworzenie, wyłączanie, wznawianie i usuwanie strumieni dziennika audytu. Wygenerowany klucz podpisujący jest wyświetlany tylko raz.',
    'record_audit_events_your_app_s_users_cause_for_the_orga_a94adc1d' => 'Zapisywanie zdarzeń audytu wywołanych przez użytkowników Twojej aplikacji w organizacjach, w których wystąpiły. Tylko uprawnienia potrzebne backendowi wysyłającemu zdarzenia.',
    'read_the_audit_events_your_app_sent_and_the_exports_mad_e424eabd' => 'Odczytywanie zdarzeń audytu wysłanych przez Twoją aplikację i ich eksportów, weryfikowanie łańcucha organizacji oraz odczytywanie schematów i zasad przechowywania tych zdarzeń.',
    'start_csv_exports_of_the_audit_events_your_app_sent_the_230b66c5' => 'Rozpoczynanie eksportu CSV zdarzeń audytu wysłanych przez Twoją aplikację — tych samych zdarzeń, które udostępnia zakres odczytu, w jednym pliku.',
    'define_replace_and_delete_the_schemas_audit_events_are_c37e0366' => 'Definiowanie, zastępowanie i usuwanie schematów walidacji zdarzeń audytu oraz zmiana okresu ich przechowywania — skrócenie tego okresu trwale usuwa starsze zdarzenia.',
    'read_the_authorization_schema_and_its_tuples_and_ask_ch_e5b3f66c' => 'Odczytywanie schematu autoryzacji i jego krotek oraz wykonywanie sprawdzeń i zapytań listujących: „Czy ten użytkownik może edytować ten dokument?”, „Które dokumenty może zobaczyć?”. Tylko uprawnienia potrzebne backendowi aplikacji do egzekwowania dostępu.',
    'write_and_delete_relationship_tuples_who_owns_edits_or_53581cba' => 'Zapisywanie i usuwanie krotek relacji — kto jest właścicielem zasobów Twojej aplikacji, kto je edytuje lub przegląda. Zapis natychmiast przyznaje lub odbiera dostęp w aplikacji.',
    'replace_the_authorization_schema_the_resource_types_and_f57d294e' => 'Zastępowanie schematu autoryzacji — typów zasobów i sposobu ustalania każdej relacji. Natychmiast zmienia odpowiedzi na wszystkie sprawdzenia w tym środowisku.',
    'read_the_authentication_policy_the_social_login_provide_758352e3' => 'Odczytywanie zasad uwierzytelniania, dostawców logowania społecznościowego i deklaracji logowania starszego typu — nigdy sekretów dostawcy.',
    'change_password_mfa_and_sso_rules_self_service_sign_up_66c7cb03' => 'Zmiana zasad haseł, MFA i SSO, samodzielnej rejestracji, dostawców logowania społecznościowego i zatwierdzenia logowania starszego typu.',
    'read_radar_s_mode_built_in_and_custom_rules_allow_and_d_3e27d38d' => 'Odczytywanie trybu Radar, reguł wbudowanych i własnych, list dozwolonych i zablokowanych oraz przeglądarki decyzji — dlaczego logowanie lub rejestracja zostały dozwolone, poddane dodatkowej weryfikacji lub zablokowane. Nigdy nie ujawnia adresu IP ani innego adresu z decyzji.',
    'write_reorder_and_delete_radar_rules_tune_the_built_in_254f1eff' => 'Tworzenie, zmiana kolejności i usuwanie reguł Radar, dostosowywanie reguł wbudowanych oraz dodawanie i usuwanie wpisów na listach dozwolonych i zablokowanych.',
    'switch_radar_between_monitor_record_only_and_enforce_bl_c3ec2073' => 'Przełączanie Radar między monitorowaniem (tylko zapisywanie) a egzekwowaniem reguł (blokowanie i dodatkowa weryfikacja) — włączanie lub wyłączanie ochrony logowania w środowisku.',
    'list_the_publishable_keys_browser_apps_present_to_the_f_9a4fe3ce' => 'Wyświetlanie kluczy publicznych aplikacji przekazywanych przez aplikacje przeglądarkowe do Frontend API wraz z dozwolonymi źródłami.',
    'create_publishable_keys_change_which_origins_may_presen_79684ec2' => 'Tworzenie kluczy publicznych aplikacji, zmiana źródeł, które mogą ich używać, i unieważnianie kluczy.',
    'list_the_applications_that_trust_this_environment_as_th_61538b0b' => 'Wyświetlanie aplikacji, które ufają temu środowisku jako dostawcy tożsamości SAML — nigdy ich certyfikatów.',
    'register_change_and_remove_the_applications_people_sign_6b6a4041' => 'Rejestrowanie, zmiana i usuwanie aplikacji, do których użytkownicy logują się za pomocą tutejszego konta.',
    'read_the_hosted_sign_in_theme_and_branding_of_the_envir_c85a3622' => 'Odczytywanie motywu i identyfikacji wizualnej hostowanego logowania dla środowiska i jego organizacji.',
    'change_the_hosted_sign_in_theme_and_branding_of_the_env_bc832c7e' => 'Zmiana motywu i identyfikacji wizualnej hostowanego logowania dla środowiska i jego organizacji.',
    'read_this_environment_s_custom_domain_and_the_dns_recor_4408e8a7' => 'Odczytywanie własnej domeny tego środowiska i potwierdzającego ją rekordu DNS.',
    'add_verify_and_remove_the_custom_domain_this_environmen_9a4835eb' => 'Dodawanie, weryfikowanie i usuwanie własnej domeny, pod którą dostępne jest to środowisko.',
    'erase_a_person_for_good_gdpr_art_17_their_credentials_s_ff46c230' => 'Trwałe usunięcie osoby (art. 17 RODO): dane uwierzytelniające, sesje, członkostwa i dane osobowe zostają usunięte, a konto zostaje spseudonimizowane. Tej operacji nie można cofnąć.',
    'create_rename_re_permission_and_delete_roles_and_author_dca95601' => 'Tworzenie, zmiana nazw i uprawnień oraz usuwanie ról, a także definiowanie składających się na nie uprawnień ręcznych. Przypisywanie ról osobom wymaga `roles:write`.',
    'list_the_saml_and_oidc_connections_organizations_sign_i_8dbbb680' => 'Wyświetlanie połączeń SAML i OIDC używanych przez organizacje do logowania oraz domen e-mail kierujących do nich użytkowników — nigdy certyfikatów, sekretów klienta ani kluczy podpisujących.',
    'create_change_enable_disable_and_delete_sso_connections_58aa8cd7' => 'Tworzenie, zmiana, włączanie, wyłączanie i usuwanie połączeń SSO, wymaganie SSO w organizacji oraz weryfikowanie jej domen e-mail i wymuszanie w nich SSO. Zmienia sposób logowania użytkowników.',
    'list_the_directories_scim_google_workspace_microsoft_en_97350786' => 'Wyświetlanie katalogów (SCIM, Google Workspace, Microsoft Entra), z których synchronizowani są użytkownicy, ich grup i błędów synchronizacji — nigdy tokenów bearer ani danych uwierzytelniających dostawcy.',
    'connect_rename_pause_re_key_and_delete_inbound_director_9cb4cce4' => 'Łączenie, zmiana nazw, wstrzymywanie, wymiana kluczy i usuwanie katalogów źródłowych oraz mapowanie ich grup na role. Nowy lub wymieniony token bearer SCIM jest wyświetlany tylko raz.',
    'list_the_downstream_scim_targets_this_environment_pushe_2753c203' => 'Wyświetlanie docelowych systemów SCIM, do których to środowisko wysyła dane użytkowników, i informacji o ich błędach — nigdy ich danych uwierzytelniających.',
    'register_pause_resume_and_delete_the_scim_targets_this_ca3c3bb1' => 'Rejestrowanie, wstrzymywanie, wznawianie i usuwanie systemów docelowych SCIM, do których to środowisko wysyła dane użytkowników.',
    'read_role_conflict_segregation_of_duties_rules_and_acce_8572d9a3' => 'Odczytywanie reguł konfliktów ról (rozdziału obowiązków) i przeglądów dostępu wraz ze wszystkimi pozycjami, których potwierdzenie jest wymagane.',
    'define_switch_and_remove_role_conflict_rules_open_acces_34e40e6c' => 'Definiowanie, włączanie, wyłączanie i usuwanie reguł konfliktów ról; otwieranie przeglądów dostępu, zapisywanie decyzji i zamykanie przeglądów — zamknięcie wykonuje wszystkie odebrania dostępu.',
    'list_the_downstream_credentials_stored_in_the_token_vau_15a080ce' => 'Wyświetlanie danych uwierzytelniających systemów docelowych zapisanych w sejfie tokenów i aplikacji, które mogą uzyskać do nich czasowy dostęp — nigdy zapisanych wartości.',
    'store_rotate_and_revoke_downstream_credentials_and_gran_86bf996c' => 'Zapisywanie, rotacja i unieważnianie danych uwierzytelniających systemów docelowych oraz przyznawanie lub odbieranie aplikacji prawa do czasowego dostępu do nich. To nie zakresy vault.manage / vault.lease zawarte we własnym tokenie aplikacji.',
    'list_feature_flags_with_their_targeting_and_evaluate_ev_92059a92' => 'Wyświetlanie flag funkcji wraz z regułami kierowania i ocenianie każdej flagi dla użytkownika w organizacji — o to pyta backend aplikacji, gdy nie ma tokenu.',
    'define_switch_retarget_and_delete_feature_flags_which_f_e64692af' => 'Definiowanie, włączanie, wyłączanie, zmiana kierowania i usuwanie flag funkcji — określanie, które funkcje otrzymują poszczególni użytkownicy i organizacje.',
    'list_the_third_party_providers_people_can_connect_their_1cc25b9b' => 'Wyświetlanie zewnętrznych dostawców, z którymi użytkownicy mogą łączyć swoje konta, aplikacji z prawem do czasowego dostępu do tych tokenów oraz osób, które połączyły konta — nigdy sekretów klienta ani tokenów.',
    'configure_change_and_remove_pipes_grant_or_withdraw_an_f69a04e9' => 'Konfigurowanie, zmiana i usuwanie integracji pipes, przyznawanie lub odbieranie aplikacji prawa do czasowego dostępu do tokenów połączonych kont oraz rozłączanie kont użytkowników.',
    'list_an_organization_s_recent_admin_portal_links_what_e_f1c55153' => 'Wyświetlanie ostatnich linków do Portalu administracyjnego organizacji: co otwierają, kto je utworzył, do kogo je wysłano i jaki mają status — nigdy samego linku.',
    'mint_a_one_time_admin_portal_link_that_lets_an_organiza_9371449a' => 'Tworzenie i wycofywanie jednorazowych linków do Portalu administracyjnego, które pozwalają administratorowi IT organizacji skonfigurować SSO, domeny lub synchronizację katalogów bez konta. Nowy link jest wyświetlany tylko raz.',
    'list_the_pending_requests_from_agents_to_act_as_one_of_67e57ec8' => 'Wyświetlanie oczekujących próśb agentów o działanie w imieniu użytkownika tego środowiska (OIDC CIBA): która aplikacja, w czyim imieniu i o co prosi.',
