    '_part1_a_code_can_be_taken_by_a_sim_swap_or_number_port_690b2597' => ':part1 Kod można przejąć przez podmianę karty SIM lub nieuprawnione przeniesienie numeru, przechwycić w sieci telefonicznej albo wyłudzić na wiarygodnie wyglądającej fałszywej stronie logowania. Nadal jest to znacznie lepsze niż samo hasło — włącz tę metodę osobom, które nie mogą korzystać z aplikacji uwierzytelniającej ani klucza dostępu.',
    '_part1_a_logo_linked_from_another_site_told_that_site_a_dcac9b85' => ':part1 Logo pobierane z innej witryny przekazywało jej informacje o każdej osobie otwierającej Twoją stronę logowania, dlatego hostowane strony wyświetlają teraz tylko obrazy przesłane tutaj. Prześlij logo poniżej w sekcji :part2 lub usuń je, aby zamknąć ten komunikat.',
    '_part1_can_sign_in_with_passwords_or_with_this_connecti_ebadb8e1' => ':part1 może logować się hasłem lub przez to połączenie. Wymaganie logowania jednokrotnego odrzuca wszystkie inne metody, więc żaden wcześniej wydany środek dostępu nie może ominąć właśnie skonfigurowanego dostawcy. Większość firm łączących IdP tego oczekuje — najpierw jednak przeczytaj, jakie są skutki.',
