    'it_is_called_again_at_the_hook_point_from_the_next_matc_a4d12b55' => 'Będzie znów wywoływany w punkcie zaczepienia hooka od następnej pasującej operacji.',
    'it_stops_being_able_to_act_as_you_immediately_and_has_t_5c3d584b' => 'Natychmiast utraci możliwość działania w Twoim imieniu i będzie musiała ponownie poprosić o Twoją zgodę.',
    'it_stops_being_called_at_the_hook_point_the_operation_i_72937229' => 'Przestanie być wywoływany w punkcie zaczepienia hooka. Obsługiwana przez niego operacja będzie kontynuowana bez niego.',
    'it_stops_working_immediately_anything_still_using_it_fa_4a9caff7' => 'Natychmiast przestanie działać. Wszystko, co nadal go używa, nie będzie mogło się zalogować.',
    'it_uses_pkce_and_gets_no_secret_nothing_to_l_f9fee647' => 'Używa PKCE i nie otrzymuje sekretu — nie ma czego wykradać z przeglądarki ani telefonu.',
    'its_events_are_accepted_unchecked_from_now_on_or_refuse_af37acad' => 'Od teraz jego zdarzenia będą przyjmowane bez sprawdzania — albo odrzucane, jeśli włączono tryb ścisły.',
    'its_members_can_sign_in_again_and_its_environments_resu_d369bd33' => 'Członkowie znów mogą się logować, a środowiska wznawiają obsługę uwierzytelniania.',
    'its_own_credentials_in_place_of_the_environment_s_for_t_bf11c9ef' => 'Własne dane uwierzytelniające zamiast danych środowiska dla tego dostawcy.',
    'key_created_paste_it_into_your_frontend_it_is_meant_to_0e59b7a5' => 'Klucz utworzony. Wklej go do frontendu — jest przeznaczony do publicznego użycia.',
    'key_rotated_copy_the_new_one_now_the_old_key_keeps_work_aedb1c3d' => 'Klucz wymieniony — skopiuj teraz nowy. Stary klucz działa jeszcze przez 24 godziny.',
    'offers_google_github_apple_and_others_as_buttons_on_you_82b5af03' => 'Wyświetla na stronie logowania przyciski Google, GitHub, Apple i innych dostawców dla osób, które wolą użyć istniejącego konta zamiast tworzyć kolejne hasło. Skonfiguruj dostawcę raz dla środowiska, a będzie dostępny we wszystkich organizacjach. Organizacja może użyć własnych danych uwierzytelniających lub wyłączyć dostawcę. Podajesz dane uwierzytelniające, a pozostałe pola są uzupełniane automatycznie. Sam adres przekazany przez dostawcę nigdy nie wystarcza do uzyskania dostępu do istniejącego tutaj konta.',
    'the_keys_your_own_code_presents_to_cbox_id_one_tab_per__a0955137' => 'Klucze, którymi Twój kod uwierzytelnia się w Cbox ID, z osobną kartą dla każdego rodzaju. Klucz tajny, czyli klucz zarządzania, pozwala backendowi zarządzać organizacjami, członkami, zaproszeniami, rolami i aplikacjami jednego środowiska. Klucz organizacji wywołuje jej API z rolą wbudowaną. Klucz publiczny trafia do aplikacji w przeglądarce i działa tylko z dozwolonych źródeł. Klucze tajne i klucze organizacji są wyświetlane tylko raz. Skopiuj je podczas tworzenia i natychmiast unieważnij w razie wycieku.',
    'registers_applications_that_accept_this_environment_as_d381d96e' => 'Rejestruje aplikacje, które uznają to środowisko za dostawcę tożsamości SAML, dzięki czemu użytkownicy logują się za pomocą posiadanych tutaj kont. Przypisz każdej aplikacji jej organizację, aby dostęp mieli tylko członkowie tej organizacji. Bez przypisanej organizacji aplikacja jest dostępna dla wszystkich użytkowników środowiska. To połączenie wychodzące. Aby umożliwić logowanie kontem firmowym z innego systemu, użyj firmowego SSO w sekcji Uwierzytelnianie.',
    'pick_the_framework_you_are_building_with_and_an_app_is_a82b6a71' => 'Wybierz framework, którego używasz. Powstanie aplikacja z przekierowaniem do lokalnego serwera deweloperskiego, blokiem konfiguracji środowiska do wklejenia oraz kodem logowania użytkownika. Strona czeka na rzeczywiste logowanie. Poniżej znajdują się kroki przygotowania produktu: identyfikacja wizualna, organizacje, jednokrotne logowanie, agent, współpracownik i środowisko produkcyjne. Ich wykonanie jest oznaczane na podstawie stanu środowiska, nigdy ręcznie.',
    'radar_judges_every_sign_in_and_sign_up_credential_stuff_96651d15' => 'Radar ocenia każde logowanie i rejestrację: próby użycia wykradzionych danych logowania, szybkość typową dla botów, niemożliwe podróże, nowe urządzenia, sieci anonimizujące i jednorazowe adresy, a także Twoje reguły oraz listy dozwolonych i zablokowanych. Zapisuje każdą decyzję, a po włączeniu egzekwowania reguł blokuje dostęp lub wymaga drugiego składnika. Sprawdź decyzje tutaj przed włączeniem egzekwowania oraz gdy ktoś zgłasza problem z logowaniem.',
    'switches_your_apps_ask_about_for_one_person_in_one_orga_e232d9a9' => 'Przełączniki funkcji, o które aplikacje pytają dla konkretnej osoby w organizacji. Włącz funkcję dla wskazanych użytkowników, organizacji lub części wszystkich użytkowników. Każda aplikacja odczyta tę samą odpowiedź, z tokenu lub API.',
    'software_that_acts_on_this_environment_with_a_managemen_24a4b34d' => 'Oprogramowanie działające w tym środowisku przy użyciu klucza zarządzania: Claude Code, Cursor, wewnętrzny bot lub własny backend. Każde ma tylko nadane mu zakresy uprawnień i czeka na zatwierdzenie tam, gdzie jest ono wymagane.',
    'your_receiver_keeps_the_same_secret_a_64_character_hex_c0d890ee' => 'Odbiornik zachowuje ten sam sekret. Sekret zapisany jako 64 znaki szesnastkowe zmienia się w whsec_ z dołączonym kodowaniem base64 tego ciągu szesnastkowego — "whsec_" + base64(secret). Sekret zaczynający się już od whsec_ jest używany bez zmian.',
    'organizations_users_and_active_sessions_for_every_envir_b7f36bfd' => 'Organizacje, użytkownicy i aktywne sesje ze wszystkich środowisk tej instalacji oraz organizacje z największą liczbą członków. Widok tylko odczytuje dane i nigdy nie zmienia środowiska wybranego w konsoli.',
    'everyone_who_can_sign_in_to_this_organization_and_the_i_e278dd18' => 'Wszystkie osoby, które mogą zalogować się do tej organizacji, oraz wysłane zaproszenia, których jeszcze nikt nie przyjął. Zapraszaj przez e-mail; każda osoba samodzielnie konfiguruje logowanie, więc nie musisz zajmować się cudzymi hasłami.',
    'let_people_sign_in_with_an_account_they_already_have_se_de3c77a6' => 'Umożliwiaj logowanie przy użyciu istniejących kont. Skonfiguruj dostawcę raz dla środowiska, a będzie dostępny we wszystkich organizacjach. Organizacja może użyć własnych danych uwierzytelniających lub wyłączyć dostawcę.',
    'radar_judges_every_sign_in_and_sign_up_credential_stuff_9c16eda1' => 'Radar ocenia każde logowanie i rejestrację: próby użycia wykradzionych danych logowania, tempo typowe dla botów, niemożliwe przemieszczenia, nowe urządzenia, sieci anonimizujące, jednorazowe adresy oraz własne reguły i listy. Zapisuje też powód decyzji.',
    'this_user_can_no_longer_sign_in_to_any_application_in_t_571ac0d8' => 'Ten użytkownik nie może już logować się do żadnej aplikacji w tym środowisku, a jego obecne sesje przestaną działać przy następnym żądaniu. Jego dane pozostają zachowane i można go ponownie aktywować w dowolnym momencie.',
    'evaluated_in_order_the_deny_list_the_allow_list_your_ru_00db2fea' => 'Kolejność oceny: lista blokad, lista dozwolonych, własne reguły od góry (decyduje pierwsza pasująca), a następnie reguły wbudowane (decyduje najsurowsza z uruchomionych). Brak dopasowania oznacza zezwolenie.',
    'most_integrations_want_webhooks_instead_those_run_after_576be07b' => 'Większość integracji powinna korzystać z webhooków: uruchamiają się po zdarzeniu i nie mogą go wstrzymać. Użyj hooka tylko wtedy, gdy Twój system musi uczestniczyć w podejmowaniu decyzji podczas logowania lub wydawania tokenu.',
    'keys_you_create_appear_here_with_when_each_was_last_use_8c3ff766' => 'Utworzone klucze pojawią się tutaj wraz z czasem ostatniego użycia.',
    'leave_empty_for_no_lockout_this_deployment_has_switched_d1f1a3e9' => 'Pozostaw puste, aby nie stosować blokady — w tym wdrożeniu domyślna blokada jest wyłączona.',
    'let_people_sign_in_with_the_company_account_they_alread_b98aff03' => 'Pozwól użytkownikom logować się istniejącym kontem firmowym zamiast osobnym hasłem tutaj.',
    'log_stream_saved_delivery_is_tried_again_on_the_next_ru_fb2e3c84' => 'Strumień dziennika zapisany. Dostarczenie zostanie ponowione przy następnym uruchomieniu.',
    'management_key_created_copy_it_now_it_will_not_be_shown_9ec713ad' => 'Klucz zarządzania utworzony — skopiuj go teraz, nie zostanie pokazany ponownie.',
    'map_a_group_onto_the_roles_everyone_in_it_should_hold_m_1a407a38' => 'Przypisz grupę do ról, które powinni mieć wszyscy jej członkowie. Członkostwo jest synchronizowane, a role zmieniają się wraz z nim.',
