    '_part1_its_team_is_administered_under_organization_team_6abad4af' => ':part1 Zespołem zarządza osoba z rolą w obszarze roboczym, w sekcji Obszar roboczy › Zespół, a nie tutaj.',
    '_part1_only_d798c565' => 'Tylko :part1',
    '_part1_part2_nothing_here_is_set_by_part3_yet_change_an_a8ead075' => ':part1 :part2 :part3 nie określa tu jeszcze żadnych ustawień — zmiana dowolnej wartości poniżej utworzy własną regułę tej organizacji.',
    '_part1_part2_only_5ce234b9' => 'Tylko :part1 :part2',
    '_part1_the_part2_claim_is_a_different_thing_it_is_what_c15748b6' => ':part1 Pole :part2 ma inne znaczenie: określa, o co mogła poprosić :part3 :part4, a nie co może robić ta :part5.',
    '_part1_tick_the_part2_part3_scope_when_you_register_the_ef0603eb' => ':part1 Podczas rejestracji aplikacji zaznacz zakres :part2 :part3. Token ID będzie zawierał te same nazwy ról w polu :part4 — właśnie tej nazwy szukają Kubernetes, Grafana i Vault. Nie trzeba tworzyć niczego więcej.',
