    'a_conflict_is_written_over_roles_so_there_is_nothing_to_1ee9ecc5' => 'Konflikt definiuje się między rolami, więc na razie nie ma czego określać. Najpierw zdefiniuj role.',
    'a_page_on_part1_leave_empty_to_land_in_the_console_with_1e303bfc' => 'Strona w :part1. Pozostaw puste, aby przejść do konsoli, z :part2 wskazanym w zaproszeniu.',
    'a_part1_key_you_can_compose_into_roles_e_g_part2_part3_2714a35b' => 'Klucz :part1, który można włączyć do ról, np. :part2.:part3 :part4',
    'a_permission_is_what_a_part1_may_do_once_signed_in_what_d4afab64' => 'Uprawnienie określa, co :part1 może robić po zalogowaniu. To, o co może poprosić :part2, jest zakresem ustawianym podczas rejestracji w :part3 :part4.',
    'a_user_rule_beats_an_organization_rule_which_beats_the_74a29528' => 'Reguła użytkownika ma pierwszeństwo przed regułą organizacji, ta przed stopniowym wdrażaniem, a ono przed wartością domyślną. Po wyłączeniu flaga jest wyłączona dla wszystkich.',
    'access_accumulates_people_change_teams_and_keep_what_th_cd6b423c' => 'Dostęp się kumuluje: ludzie zmieniają zespoły, ale zachowują stare uprawnienia, czego nikt nie zauważa aż do pytania audytora. Przegląd zapisuje bieżący stan uprawnień i wymaga potwierdzenia dla każdego nadania, czy jest nadal potrzebne.',
    'access_tokens_for_this_app_name_part1_as_their_audience_0da966a0' => 'Tokeny dostępu tej aplikacji wskazują :part1 jako odbiorcę :part2. To API powinno przyjmować token tylko wtedy, gdy jest w nim wskazane.',
    'access_tokens_for_this_app_name_this_environment_s_issu_13b4d3ef' => 'Tokeny dostępu tej aplikacji wskazują jako odbiorcę wystawcę tego środowiska,:part1 :part2. Zmienia się to, gdy aplikacja ma zakres jednego z zarejestrowanych API.',
    'acme_dashboard_0b433bd7' => 'Panel Acme',
