    'an_app_registered_here_can_sign_your_people_in_and_read_f35bdb6c' => 'Zarejestrowana tutaj aplikacja może logować Twoich użytkowników i odczytywać ich role, dzięki czemu zarządzasz dostępem w jednym miejscu zamiast osobno w każdym produkcie.',
