    'type_the_organization_s_name_exactly_as_shown_to_confir_f021127d' => 'Aby potwierdzić, wpisz nazwę organizacji dokładnie tak, jak jest wyświetlona.',
    'typed_scopes_part1_are_unowned_they_travel_as_they_are_e061e25f' => 'Ręcznie wpisane zakresy (:part1) nie mają właściciela: są przekazywane bez zmian i nigdy z odbiorcą zarejestrowanego API.',
    'until_an_api_is_registered_a_scope_is_just_text_on_an_a_db7d3254' => 'Dopóki API nie jest zarejestrowane, zakres jest tylko tekstem w aplikacji, a każdy, kto może ją edytować, może nadać jej dowolny zakres. Zarejestruj API wywoływane przez aplikacje, aby ich zakresy miały właściciela.',
    'user_alice_dabd1db8' => 'user:alice',
    'ux_advanced_help' => 'Ustawienia opcjonalne. Wartości domyślne odpowiadają większości aplikacji.',
    'ux_scopes_summary' => 'Wybrane uprawnienia: :count',
    'we_could_not_send_that_invitation_the_mail_server_refus_81a3f4df' => 'Nie udało się wysłać zaproszenia — serwer poczty je odrzucił. Nic nie utworzono; spróbuj ponownie albo sprawdź konfigurację poczty tej instalacji.',
    'what_an_app_may_be_allowed_to_do_at_this_api_only_part1_c0ec6f18' => 'Co można zezwolić aplikacji robić w tym API. Te zakresy mogą mieć tylko własne aplikacje :part1.',
    'what_an_app_may_be_allowed_to_do_at_this_api_your_own_a_94f7133a' => 'Co można zezwolić aplikacji robić w tym API. Twoje aplikacje mogą mieć dowolny z tych zakresów; aplikacja zarejestrowana przez organizację tylko zakresy oznaczone jako dostępne dla organizacji.',
    'what_apps_ask_for_such_as_invoices_read_unique_in_this_2109e70c' => 'To, o co proszą aplikacje, na przykład invoices:read. Unikalne w tym środowisku.',
    'what_people_can_do_inside_your_apps_you_assign_roles_he_c31f1a20' => 'Co ludzie mogą robić w Twoich aplikacjach. Tutaj przypisujesz role; każda aplikacja decyduje, na co pozwalają jej role.',
    'what_this_role_is_allowed_to_do_tick_a_permission_to_gr_518298cc' => 'Co może robić ta rola. Zaznacz uprawnienie, aby je przyznać; odznacz, aby je cofnąć.',
    'what_this_round_is_called_when_somebody_asks_which_revi_6e0713c0' => 'Nazwa tej rundy, która pozwala ustalić, z którego przeglądu pochodzi decyzja — kwartał, audyt lub data.',
    'what_your_code_asks_for_and_what_the_feature_flags_clai_440d8ca1' => 'To, o co pyta Twój kod i co zawiera pole feature_flags. Małe litery i cyfry, rozdzielane znakami - _ lub . Nie można tego później zmienić.',
    'whatever_is_using_this_key_stops_working_immediately_th_8e55e6f5' => 'Wszystko, co używa tego klucza, natychmiast przestaje działać. Tej operacji nie można cofnąć.',
    'whatever_the_holder_has_wired_this_key_into_stops_worki_e14495d2' => 'Wszystko, do czego użytkownik podłączył ten klucz, natychmiast przestaje działać. Jeśli możesz, uprzedź go. Tej operacji nie można cofnąć.',
    'when_somebody_creates_an_api_key_for_one_of_your_apps_i_15c6370c' => 'Gdy ktoś utworzy klucz API dla jednej z Twoich aplikacji, pojawi się tutaj wraz z informacją, kto go ma i co może robić.',
    'when_somebody_signs_out_or_an_administrator__3520d247' => 'Gdy ktoś się wyloguje albo administrator zakończy jego sesje, usunie go lub dezaktywuje, Cbox ID wysyła podpisany token wylogowania na ten adres, bezpośrednio między serwerami, aby aplikacja mogła również zakończyć własną sesję.',
    'where_cbox_id_sends_people_after_they_sign_out_of_this_3a65532f' => 'Miejsce, do którego Cbox ID kieruje użytkowników po wylogowaniu z tej aplikacji. URI żądany przez aplikację musi dokładnie odpowiadać wpisowi na liście, łącznie z końcowym ukośnikiem. W przeciwnym razie Cbox ID pozostawia użytkownika na własnej stronie po wylogowaniu. Pozostaw puste, jeśli aplikacja nie przekierowuje użytkowników po wylogowaniu.',
    'where_this_app_publishes_the_roles_it_unders_e6047562' => 'Gdzie aplikacja publikuje obsługiwane role, aby można je było tutaj przypisywać.',
    'which_ways_in_part1_offers_besides_a_password_and_how_l_37522a30' => 'Jakie metody dostępu poza hasłem oferuje :part1 i jak długo trwa zalogowanie. Są jednakowe dla każdej organizacji w tym środowisku.',
    'who_belongs_to_this_organization_and_what_they_can_do_s_330bf97e' => 'Kto należy do tej organizacji i co może robić. Osoba, która nie ma tu jeszcze konta, otrzyma zaproszenie e-mailem.',
    'who_gets_the_flag_when_no_rule_names_them_leave_it_off_b44a0c73' => 'Kto otrzymuje flagę, gdy nie wskazuje go żadna reguła. Pozostaw wyłączone, aby najpierw wdrożyć funkcję dla wskazanych organizacji lub części użytkowników.',
    'whose_role_it_is_or_tick_the_box_above_to_define_it_for_970fb7fe' => 'Do kogo należy rola — albo zaznacz powyższe pole, aby zdefiniować ją dla wszystkich organizacji.',
    'whose_roles_and_memberships_the_review_snapshots_e7576353' => 'Czyje role i członkostwa zapisuje przegląd.',
    'whose_rule_it_is_or_tick_the_box_above_to_apply_it_to_e_82370728' => 'Do kogo należy reguła — albo zaznacz powyższe pole, aby zastosować ją do wszystkich organizacji.',
    'without_roles_everyone_who_can_sign_in_gets_whatever_an_dc1418f9' => 'Bez ról każda osoba, która może się zalogować, otrzymuje dostęp przewidziany w aplikacji dla zwykłego użytkownika. Rola pozwala raz określić, kto jest redaktorem, a kto pracownikiem pomocy, i stosować ten podział we wszystkich połączonych aplikacjach.',
    'work_through_the_list_certify_what_is_still_needed_revo_9bcc79ab' => 'Przejdź przez listę: potwierdź to, co nadal jest potrzebne, i cofnij resztę.',
    'write_one_above_or_from_your_app_s_backend_in_batches_o_9ca507a7' => 'Zapisz jedną powyżej lub przesyłaj je z backendu aplikacji w partiach do 100.',
    'writes_531995e8' => 'zapis',
    'you_are_the_only_owner_transfer_ownership_to_someone_el_1e7b6195' => 'Jesteś jedynym właścicielem. Najpierw przenieś własność na kogoś innego albo usuń organizację.',
    'you_can_also_part1_part2_part3_53f32513' => 'Inna możliwość: :part1 :part2. :part3',
    'you_can_set_this_back_to_prefer_sso_or_both__b84203a4' => 'W każdej chwili możesz przywrócić „Preferuj SSO” lub „Obie dostępne”; zakończone sesje pozostają zakończone.',
    'you_can_set_this_back_to_prefer_sso_or_both_available_a_b84203a4' => 'W każdej chwili możesz przywrócić „Preferuj SSO” lub „Obie dostępne”; zakończone sesje pozostają zakończone.',
    'you_lose_access_immediately_as_its_owner_you_can_only_l_d51a2272' => 'Natychmiast tracisz dostęp. Jako właściciel możesz odejść dopiero wtedy, gdy ktoś inny przejmie własność — najpierw ją przenieś albo usuń organizację w Ustawieniach.',
    'you_lose_access_to_this_organization_and_its_apps_immed_47fdba25' => 'Natychmiast tracisz dostęp do tej organizacji i jej aplikacji. Administrator może zaprosić Cię ponownie.',
    'your_app_s_own_access_model_resource_types_the_relation_3dddc87d' => 'Własny model dostępu aplikacji: typy zasobów, relacje dla każdego typu i zasady dziedziczenia. Aplikacja zapisuje krotki określające, kto jest powiązany z czym, i sprawdza uprawnienia przy każdym żądaniu.',
    'your_authentication_policy_still_applies_password_stren_84825ce9' => 'Twoje zasady uwierzytelniania nadal obowiązują: siła hasła, sprawdzanie wycieków, potwierdzanie e-maila, limity częstotliwości i ochrona przed botami.',
    'your_own_api_you_choose_scope_by_scope_which_of_its_sco_6f77f332' => 'Twoje własne API. Dla każdego zakresu wybierasz, czy aplikacje zarejestrowane przez organizacje mogą o niego prosić.',
    'your_sign_in_page_gets_a_create_an_account_link_and_app_8a665905' => 'Na stronie logowania pojawi się link „Utwórz konto”, a aplikacje mogą kierować użytkowników bezpośrednio do rejestracji za pomocą :part1.',
    'roles_and_permissions_arrive_in_the_access_token_as_two_0107aa88' => 'Role i uprawnienia w tokenie są obrazem stanu z chwili jego wydania. Przed każdą chronioną operacją uzyskaj aktualną decyzję o dostępie z Cbox ID i sprawdź w aplikacji dostęp do konkretnego zasobu. Sama zawartość tokenu nie odzwierciedla późniejszego cofnięcia dostępu:',
    'your_own_sign_in_methods_and_active_sessions_a_passkey_2bf79cbb' => 'Twoje metody logowania i aktywne sesje. Klucz dostępu to najbezpieczniejsza i najszybsza opcja: urządzenie odblokowuje go odciskiem palca lub rozpoznaniem twarzy, a hasła, które można wykraść przez phishing, nie ma.',
    'every_action_is_accepted_as_your_app_sends_it_add_a_sch_fce48faa' => 'Każda akcja jest przyjmowana w postaci przesłanej przez aplikację. Dodaj schemat akcji, aby jej zdarzenia były sprawdzane po otrzymaniu. O spójność dziennika dba się przy zapisie zdarzenia, a nie dopiero przy odczycie.',
    'every_api_key_sitting_in_an_app_s_config_or_environment_975161a8' => 'Każdy klucz API zapisany w konfiguracji aplikacji lub pliku środowiska to klucz, którego nie można centralnie wymienić ani szybko odebrać. Przechowywany tutaj jest szyfrowany, udostępniany osobno każdej aplikacji i możliwy do cofnięcia jednym kliknięciem.',
    'it_stops_appearing_as_a_button_and_its_credentials_are_120d1fa5' => 'Przycisk przestanie się wyświetlać, a dane uwierzytelniające zostaną usunięte. Osoby, które logowały się przez tego dostawcę, zachowają konta i nadal mogą używać hasła. Jeśli chcesz zachować dane uwierzytelniające, wyłącz dostawcę zamiast go usuwać.',
    'the_mirror_image_cbox_id_pushes_your_people_into_the_ot_19c0ed40' => 'Działanie w drugą stronę: Cbox ID przesyła osoby z Twojej firmy do innych używanych przez nią produktów SaaS przez ich punkty końcowe SCIM. Jedno miejsce do nadawania i odbierania dostępu zamiast osobnego panelu administracyjnego każdego dostawcy.',
    'creates_the_organization_its_owner_its_first_product_an_79cca112' => 'Tworzy organizację, jej właściciela, pierwszy produkt i środowisko produkcyjne tego produktu. Właściciel otrzyma e-mailem link do ustawienia własnego hasła — nie wybierasz go za niego.',
    'today_somebody_adds_and_removes_people_here_by_hand_con_01774e72' => 'Obecnie ktoś ręcznie dodaje i usuwa tutaj osoby. Połącz katalog, który Twoja firma już prowadzi, a obie czynności będą wykonywane automatycznie — także usuwanie, o którym najłatwiej zapomnieć.',
    'every_token_it_issued_is_revoked_now_and_no_new_sign_in_e0dca49c' => 'Wszystkie wydane przez niego tokeny są teraz unieważniane i nie można go użyć do nowego logowania. Aplikacja, która samodzielnie sprawdza tokeny, przestanie je akceptować po ich wygaśnięciu, nie później niż z końcem samej sesji.',
    'while_you_are_migrating_off_another_system_your_app_can_a0c796b9' => 'Podczas migracji z innego systemu aplikacja może wskazać w swoim manifeście, obok ról, gdzie działa dotychczasowe logowanie. Ta informacja pojawi się tutaj do zatwierdzenia, zanim zacznie działać.',
    'write_one_to_allow_challenge_or_block_on_what_you_know_9a9a03a4' => 'Utwórz regułę zezwalającą, wymagającą dodatkowej weryfikacji lub blokującą na podstawie wiedzy o użytkownikach. Wymagaj dodatkowej weryfikacji logowań z krajów, w których nie działasz, lub zwolnij sieć biurową z reguł częstotliwości.',
    'verifying_a_domain_you_own_acme_com_lets_cbox_id_recogn_7a9ae408' => 'Zweryfikowanie własnej domeny, np. acme.com, pozwala Cbox ID rozpoznawać osoby po adresie e-mail i kierować je prosto do Twojego dostawcy, bez wybierania właściwego przycisku logowania.',
    'an_identity_provider_that_imports_service_provider_meta_9cbb9457' => 'Dostawca tożsamości importujący metadane dostawcy usługi przyjmuje ten adres URL zamiast osobnego wprowadzania identyfikatora jednostki i adresu ACS. Działa on jeszcze przed uzupełnieniem części konfiguracji dotyczącej dostawcy tożsamości.',
    'this_cannot_be_undone_their_credentials_memberships_and_0d29eed0' => 'Tej operacji nie można cofnąć. Dane uwierzytelniające, członkostwa i dane osobowe zostaną usunięte, a konto zostanie pseudonimizowane. Jeśli ta osoba jest jedynym właścicielem organizacji, najpierw przenieś jej własność.',
    'you_act_as_this_person_in_their_session_with_their_acce_36ea7fac' => 'Działasz jako ta osoba, w jej sesji i z jej uprawnieniami. Dostęp jest ograniczony do 30 minut i tylko do odczytu tam, gdzie konsola może to wymusić. Każde żądanie jest zapisywane pod Twoim nazwiskiem.',
    'suspension_is_the_only_thing_this_page_changes_and_it_i_4b1a3610' => 'Zawieszenie to jedyna zmiana wprowadzana na tej stronie i można je cofnąć. Wskazanie i otwarcie środowiska zmienia tylko widok konsoli; nie zmienia niczego w żadnym ze środowisk.',
    'right_now_people_sign_in_with_credentials_held_here_con_4538c692' => 'Obecnie osoby logują się przy użyciu przechowywanych tutaj danych uwierzytelniających. Połącz swojego dostawcę, aby korzystały z istniejącego konta firmowego i traciły tutaj dostęp w chwili jego wyłączenia u dostawcy.',
    'no_new_secret_is_issued_from_the_next_attempt_retries_i_eba13c7b' => 'Nowy sekret nie jest wydawany. Od następnej próby, również przy ponowieniach, dostarczenia będą zawierały nagłówki drugiego schematu. Nieaktualizowany odbiornik odrzuci każde z nich.',
    'send_this_single_use_link_to_whoever_runs_their_identit_ecdd3fd5' => 'Wyślij ten jednorazowy link osobie zarządzającej ich dostawcą tożsamości, jeśli nie otrzymała go e-mailem. Do czasu wygaśnięcia działa bez konta. Skopiuj go teraz — jest wyświetlany tylko raz.',
    'what_software_in_this_environment_is_waiting_for_a_pers_7aa0659a' => 'Oprogramowanie w tym środowisku oczekujące na zgodę człowieka. Agent, którego klucz wymaga zatwierdzenia, zatrzymuje się i pyta osobę, która utworzyła klucz. Odpowiedz tutaj lub na telefonie.',
    'an_organization_is_where_users_sign_in_methods_and_role_ae379847' => 'Organizacja skupia użytkowników, metody logowania i role. Utwórz ją powyżej lub zainicjuj środowisko pierwszą organizacją i administratorem na ekranie Środowiska.',
    'add_them_to_one_below_to_grant_access_inside_it_or_if_y_386e5f3c' => 'Dodaj tę osobę do jednej z poniższych organizacji, aby przyznać jej dostęp wewnątrz niej. Jeśli aplikacje nie mają własnego podziału na organizacje, nadaj jej rolę administracji i pomocy, obowiązującą w całym środowisku.',
    'an_admin_support_role_is_a_role_you_grant_to_your_own_p_caea5beb' => 'Rola administracji i pomocy to rola przyznawana własnym pracownikom w całym środowisku. Obowiązuje w każdej organizacji, a administratorzy organizacji nie mogą jej zobaczyć ani zmienić.',
    'requests_appear_here_on_their_own_when_an_app_or_agent_2ee57630' => 'Żądania pojawiają się tutaj automatycznie, gdy aplikacja lub agent potrzebuje Twojej zgody na działanie w Twoim imieniu. Dopóki nie ma żądań, nie musisz nic robić. Odrzuć każde żądanie, którego nie zainicjowano z Twojej strony.',
    'text_messages_are_the_weakest_second_step_so_fad83e4a' => 'SMS to najsłabszy drugi składnik: osoba, która przejmie Twój numer telefonu, otrzyma Twoje kody. Wybieraj aplikację uwierzytelniającą lub klucz dostępu, a SMS używaj tylko wtedy, gdy nie możesz skorzystać z tych opcji.',
    'your_environment_s_default_brand_the_hosted_sign_in_s_l_aae9270b' => 'Domyślna identyfikacja wizualna środowiska: wygląd hostowanej strony logowania, logo, favicon oraz nazwa i nadawca widoczni dla użytkowników. Każda organizacja dziedziczy te ustawienia, chyba że określi własne.',
    'organization_detail_in_the_target_environment_members_s_caef589f' => 'Szczegóły organizacji w środowisku docelowym: członkowie, SSO, domeny, uprawnienia i ostatnia aktywność. Na tej stronie można zmienić jedynie status organizacji.',
    'every_organization_on_this_install_open_one_to_walk_its_f0bd9340' => 'Wszystkie obszary robocze tej instalacji. Otwórz obszar, aby przeglądać jego produkty i środowiska. Zawieszenie wylogowuje członków i uniemożliwia wszystkim jego środowiskom obsługę uwierzytelniania.',
    'your_app_sends_these_one_call_per_batch_of_events_each_42f272f6' => 'Te zdarzenia wysyła aplikacja: jedno wywołanie na partię, a każde zdarzenie wskazuje organizację, w której wystąpiło. W miarę napływania pojawiają się tutaj oraz u administratorów tej organizacji.',
    'the_whole_environment_offers_it_on_every_sign_in_page_c_6d75dee5' => 'Jest dostępny na każdej stronie logowania w całym środowisku. Wybierz organizację, aby skonfigurować jej własnego dostawcę, który zastąpi dostawcę środowiska na stronie tej organizacji.',
    'claude_code_opens_your_browser_to_sign_in_here_and_asks_a86b6b5e' => 'Claude Code otwiera przeglądarkę, aby zalogować się tutaj, i pyta, na co pozwalasz. Nie trzeba przechowywać klucza. Każdy klient MCP logujący się przez OAuth działa tak samo z tym adresem URL.',
    'one_organization_on_this_install_its_team_its_projects__42711bef' => 'Jeden obszar roboczy tej instalacji: jego zespół, projekty i wszystkie środowiska należące do tych projektów. Zawieszenie wylogowuje członków i zatrzymuje obsługę uwierzytelniania we wszystkich tych środowiskach.',
    'environment_wide_anyone_with_an_account_in_this_environ_c60d926c' => 'W całym środowisku: każda osoba z kontem w tym środowisku, w dowolnej organizacji, może zalogować się do aplikacji. Wskaż organizację, jeśli nie chodzi Ci o tak szeroki dostęp.',
    'letting_your_people_sign_in_with_entra_id_okta_or_googl_10c80076' => 'Logowanie przez Entra ID, Okta lub Google Workspace jest dostępne w planie Enterprise. Skontaktuj się z zespołem opiekującym się Twoim kontem, aby włączyć je dla tej organizacji.',
    'where_you_are_signed_in_what_can_act_as_you_and_what_ha_874bdb24' => 'Gdzie masz aktywne sesje, co może działać w Twoim imieniu i co działo się z Twoim kontem. Jeśli widzisz coś nierozpoznanego, zakończ tę sesję i zmień hasło.',
    'how_many_people_signed_in_and_how_often_your_apps_calle_bc3b092f' => 'Ile osób się logowało i jak często aplikacje wywoływały API w ostatnich 30 dniach. Te dane służą do obserwowania obciążenia i wykrywania anomalii; nie są fakturą.',
    'this_user_owns_or_administers_an_organization_and_those_941764ef' => 'Ten użytkownik jest właścicielem lub administratorem organizacji, więc nie można się pod niego podszyć. Przejęcie takiej sesji mogłoby dać osobie podszywającej się trwałą kontrolę nad organizacją.',
    'api_keys_your_apps_and_agents_present_to_other_services_ab18c348' => 'Klucze API przedstawiane innym usługom przez aplikacje i agentów. Każda wartość jest szyfrowana podczas przechowywania, przekazywana tylko upoważnionym aplikacjom i nigdy ponownie nie wyświetla się po zapisaniu.',
    'apps_asking_to_act_on_one_of_your_users_behalf_each_use_4583b737' => 'Aplikacje proszące o możliwość działania w imieniu jednego z użytkowników. Każdy użytkownik zatwierdza własne żądania. Odrzuć żądanie tutaj tylko wtedy, gdy wygląda na nadużycie; odmowa zostanie zapisana w dzienniku audytu.',
    'how_often_to_pull_and_which_of_the_hr_system_s_own_fiel_54dd88fe' => 'Jak często pobierać dane i które pola systemu kadrowego kopiować do każdej osoby, np. centrum kosztów lub lokalizację. Zmiana pól powoduje pełne wykonanie następnej synchronizacji.',
    'links_handed_to_this_organization_s_it_administrator_th_65719b81' => 'Linki przekazane administratorowi IT tej organizacji, które nadal dają dostęp. Cofnięcie linku natychmiast go unieważnia; wcześniej utworzona przez niego konfiguracja pozostaje.',
    'requests_from_agents_asking_to_act_on_a_user_s_behalf_a_c8d607b8' => 'Żądania agentów proszących o działanie w imieniu użytkownika pojawiają się tutaj na bieżąco. Każdy użytkownik zatwierdza własne żądania. Ta strona służy do odrzucania tych, które wyglądają na nadużycie.',
    'when_every_condition_holds_radar_takes_this_rule_s_acti_1e685d20' => 'Gdy spełnione są WSZYSTKIE warunki, Radar wykonuje działanie tej reguły i nie sprawdza następnych. Reguły są sprawdzane po listach dozwolonych i blokowanych, a przed regułami wbudowanymi.',
    'the_audit_events_your_app_sends_about_the_organizations_19cde284' => 'Zdarzenia audytu wysyłane przez aplikację o wszystkich obsługiwanych organizacjach, od najnowszych. Zdarzenia każdej organizacji tworzą osobny łańcuch skrótów.',
    'everything_your_organization_has_set_up_and_what_is_lef_2eaad20f' => 'Wszystko, co organizacja już skonfigurowała, i to, co pozostało do zrobienia. Lista kontrolna śledzi rzeczywisty stan: krok zostaje automatycznie oznaczony jako ukończony, gdy faktycznie jest gotowy.',
    'as_an_administrator_add_an_authenticator_app_935b1e4e' => 'Jako administrator dodaj również aplikację uwierzytelniającą lub klucz dostępu. Przejęcie numeru telefonu pozwala przechwytywać SMS-y, więc nie mogą być jedynym drugim składnikiem.',
    'deleting_this_organization_tears_down_every_project_and_0d442c8e' => 'Usunięcie tego obszaru roboczego usuwa wszystkie należące do niego projekty i środowiska. Aby chronić działających dostawców tożsamości, operacja nie jest samoobsługowa. Skontaktuj się z pomocą, aby ją wykonać.',
    'they_lose_access_to_every_platform_page_on_this_install_0e71b790' => 'Ta osoba natychmiast traci dostęp do wszystkich stron platformy w tej instalacji, a jej obecne sesje przestaną działać przy następnym żądaniu. Możesz ją tutaj ponownie aktywować.',
    'verified_domains_route_people_to_your_own_identity_prov_127a9e78' => 'Zweryfikowane domeny kierują użytkowników do własnego dostawcy tożsamości. Ta funkcja jest częścią planu Enterprise. Skontaktuj się z zespołem opiekującym się kontem, aby włączyć ją dla tej organizacji.',
    'a_permission_is_one_thing_a_role_is_allowed_to_do_creat_522b0034' => 'Uprawnienie określa jedną czynność, którą rola może wykonać, na przykład tworzenie faktur lub odczyt raportów. Możesz definiować własne uprawnienia tutaj, bez pisania kodu, a potem łączyć je w role. Aplikacje mogą też rejestrować swoje uprawnienia automatycznie, aby lista odpowiadała rzeczywiście egzekwowanym regułom. Uprawnienia utworzone przez Ciebie należą do Ciebie. Z uprawnień udostępnionych przez środowisko możesz korzystać, ale nie możesz ich zmieniać.',
    'the_password_rules_lockout_two_factor_requirement_and_s_6d5c4102' => 'Zasady haseł, blokady oraz wymóg drugiego składnika i jednokrotnego logowania obowiązujące przy każdym logowaniu. Dla całego środowiska określasz też dostępność kluczy dostępu i linków logowania oraz czas trwania sesji. Środowisko ustala podstawowe zasady dziedziczone przez wszystkie organizacje. Organizacja może zaostrzyć zasady haseł i drugiego składnika, ale nie może ich złagodzić.',
    'what_agents_in_this_environment_are_waiting_for_a_perso_8f2ea5c0' => 'Akcje, na których zatwierdzenie przez człowieka czekają agenci w tym środowisku. Agent, którego klucz wymaga zatwierdzenia akcji, zatrzymuje się i pyta osobę, która utworzyła klucz. Może ona odpowiedzieć na telefonie lub tutaj. Każdy administrator środowiska może odrzucić podejrzane żądanie. Poniżej znajdują się prośby aplikacji o działanie w imieniu użytkowników, które każdy użytkownik zatwierdza osobiście.',
    'their_sessions_and_tokens_are_revoked_their_passkeys_se_78603573' => 'Sesje i tokeny tej osoby zostaną unieważnione. Jej klucze dostępu, drugie składniki, członkostwa, przypisania ról, tokeny API, sekrety w sejfie, urządzenia i wszystkie zapisane kopie jej danych zostaną usunięte. Z konta pozostanie jedynie pseudonimizowany, wyłączony rekord. Aplikacje synchronizujące stąd osoby otrzymają polecenie usunięcia tej osoby. Dziennik audytu zachowa niejawny identyfikator, bez imienia, nazwiska i adresu.',
    'anything_you_approved_including_a_device_or_a_command_l_eea3fafc' => 'Wszystko, co zatwierdzisz — w tym urządzenia i narzędzia wiersza poleceń, w których się zalogujesz.',
    'anything_your_own_systems_need_to_keep_against_this_org_c911b38e' => 'Dane, które twoje systemy muszą przechowywać dla tej organizacji. Wiersze bez klucza są pomijane.',
    'asked_after_your_own_rules_every_one_that_fires_is_reco_8f7f4b96' => 'Sprawdzane po twoich regułach. Każda uruchomiona reguła jest zapisywana; decyduje najbardziej restrykcyjna.',
    'delivery_resumes_entries_written_while_it_was_off_are_s_c6e7d5a4' => 'Wysyłanie zostanie wznowione. Wpisy zapisane podczas przerwy nadal oczekują i zostaną wysłane w następnej partii.',
    'delivery_stops_immediately_and_the_stored_credential_is_735dadec' => 'Wysyłanie zatrzyma się natychmiast, a zapisane dane uwierzytelniające zostaną zniszczone. Dziennik audytu pozostanie bez zmian.',
    'every_link_between_cbox_id_and_another_system_in_one_pl_0376dee4' => 'Wszystkie połączenia między Cbox ID a innymi systemami w jednym miejscu: jednokrotne logowanie, logowanie społecznościowe, synchronizacja katalogów i systemy HR, wychodzące zarządzanie kontami, aplikacje SAML, webhooki, hooki, strumienie dzienników i potoki. Katalog pozwala rozpocząć konfigurację dowolnego z nich — każda karta otwiera stronę ustawień danego rodzaju. Lista połączeń pokazuje wszystkie istniejące połączenia wraz ze stanem, zaczynając od tych z błędami.',
    'every_way_a_person_can_sign_in_here_password_passkeys_m_1abc176e' => 'Wszystkie sposoby logowania dostępne tutaj — hasło, klucze dostępu, link logowania, konto społecznościowe, firmowe SSO i drugi składnik — wraz z informacją o włączeniu i miejscu zmiany ustawień. Większość określa środowisko, a połączenia SSO należą do poszczególnych organizacji. Jeśli metoda jest wyłączona lub ograniczona w konfiguracji wdrożenia, strona informuje o tym i wskazuje odpowiednie ustawienie.',
    'an_agent_is_any_software_that_acts_on_this_environment_05aebde2' => 'Agent to dowolne oprogramowanie działające w tym środowisku z kluczem zarządzania: asystent AI, taki jak Claude Code lub Cursor, wewnętrzny bot albo Twój backend. Przydziel każdemu osobny klucz tylko z potrzebnymi zakresami. Określ, które akcje mają czekać na zatwierdzenie, i unieważnij klucz, gdy agent zakończy pracę lub coś wzbudzi podejrzenia.',
    'an_api_is_a_service_of_yours_that_receives_access_token_2747c516' => 'API to Twoja usługa otrzymująca tokeny dostępu, na przykład https://api.example.com. Zarejestruj ją wraz z obsługiwanymi zakresami, aby móc je przydzielać. Decydujesz, o które zakresy mogą prosić aplikacje rejestrowane przez organizacje w tym środowisku. Token przeznaczony dla API zawiera jego adres jako odbiorcę, którego Twoja usługa sprawdza.',
    'how_the_audit_trail_leaves_cbox_id_a_scheduled_export_s_3da9deb4' => 'Sposób przekazywania ścieżki audytu poza Cbox ID: zaplanowany eksport wysyła nowe wpisy do SIEM lub archiwum co pięć minut. Codzienne zadanie retencji tworzy punkt kontrolny bez usuwania danych. Tutaj pobierzesz historię audytu jednej osoby na potrzeby żądania dostępu zgodnie z RODO lub sprawdzisz w konsoli środowiska, czy eksport działa.',
    'exactly_as_shown_part1_stays_disabled_until_it_matches_fa10ae07' => 'Wpisz dokładnie tak, jak pokazano. Przycisk „:part1” pozostaje nieaktywny, dopóki tekst się nie zgadza.',
    'my_part1_app_40bca4ad' => 'Moja aplikacja :part1',
    'one_long_running_process_php_artisan_queue_autoscale_st_9e4a3b67' => 'Jeden długotrwały proces, php artisan queue:autoscale, uruchamia i zatrzymuje procesy robocze przetwarzające zadania z kolejki.',
    'this_will_allow_part1_to_6ac64554' => 'Aplikacja :part1 będzie mogła:',
    'totp_added_on' => 'Dodano :date',
    'totp_rename_named' => 'Zmień nazwę :name',
    'account_menu_value0_6ab6a9a2' => 'Menu konta — :value0',
    'disconnect_value0_1d09db11' => 'Odłączyć :value0?',
    'remove_value0_b597e5fb' => 'Usuń :value0',
    'rename_value0_b709cc6f' => 'Zmień nazwę :value0',
    'value0_not_included_in_this_organization_s_p_a6447bb1' => ':value0 Nie jest objęte planem tej organizacji.',
    'create_one_on_platform_environments_and_its_counts_appe_2e1a2d8f' => 'Utwórz je w Platforma › Środowiska, a jego statystyki pojawią się tutaj.',
    'every_environment_on_this_install_and_how_much_of_the_e_1d09cf29' => 'Wszystkie środowiska tej instalacji i udział każdego z nich w całości',
    'every_queue_this_install_sends_background_work_through_562c4113' => 'Wszystkie kolejki zadań w tle tej instalacji i czas oczekiwania najstarszego zadania w każdej z nich',
    'every_usage_counter_for_this_window_and_the_raw_metric_22633817' => 'Wszystkie liczniki użycia w tym okresie i oryginalne klucze odpowiadających im metryk',
    'find_an_organization_or_a_user_across_every_environment_e71f4ea0' => 'Znajdź organizację lub użytkownika we wszystkich środowiskach, nie tylko w tym wybranym w konsoli.',
    'no_claimed_domain_matches_that_try_part_of_the_domain_w_1212eb45' => 'Żadna zgłoszona domena nie pasuje. Spróbuj wpisać część domeny bez @.',
    'no_connections_match_that_name_try_a_different_search_t_6555c50e' => 'Żadne połączenie nie pasuje do tej nazwy. Spróbuj innego wyszukiwanego hasła.',
    'no_directory_matches_that_name_try_a_different_search_t_bfc6957c' => 'Żaden katalog nie pasuje do tej nazwy. Spróbuj innego wyszukiwanego hasła.',
    'no_endpoint_url_matches_that_search_try_a_different_one_45378b36' => 'Żaden adres URL punktu końcowego nie pasuje. Spróbuj innego zapytania.',
    'no_entry_matches_those_filters_try_a_broader_term_or_cl_afd8d040' => 'Żaden wpis nie pasuje do tych filtrów. Spróbuj ogólniejszego hasła lub usuń filtr.',
    'no_log_stream_matches_that_name_try_a_different_search_ac9bbc7c' => 'Żaden strumień dziennika nie pasuje do tej nazwy. Spróbuj innego zapytania.',
    'no_outbound_connection_matches_that_name_try_a_differen_2fb976c3' => 'Żadne połączenie wychodzące nie pasuje do tej nazwy. Spróbuj innego zapytania.',
    'everything_your_people_see_of_your_brand_on_one_page_th_9d98e332' => 'Wszystkie elementy marki widoczne dla użytkowników na jednej stronie: logo, favicon, kolory, krój pisma i zaokrąglenia hostowanej strony logowania z podglądem na żywo, a także nazwa produktu, nadawca e-maili i wiadomość powitalna. Ustaw je raz dla całego środowiska, aby dziedziczyły je wszystkie organizacje, lub nadaj organizacji własny wygląd na karcie Identyfikacja wizualna.',
    'each_project_in_your_organization_has_its_own_plan_and__0a007c9c' => 'Każdy projekt w organizacji ma własny plan i limit środowisk. Są one pokazane tutaj obok zużycia w tym miesiącu: organizacji, rozliczanych połączeń jednokrotnego logowania i logowań. Cena zależy od liczby aktywnych użytkowników miesięcznie oraz połączeń firmowych, takich jak SSO i SCIM. W środowiskach testowych nie nalicza się opłat za połączenia.',
    'every_api_key_the_people_in_this_organization_have_crea_51e4cae3' => 'Wszystkie klucze API utworzone przez osoby z tej organizacji dla jej aplikacji: właściciel, aplikacja, uprawnienia i ostatnie użycie. Klucz może robić tylko to, co jego właściciel, i przestaje działać, gdy właściciel opuszcza organizację. Unieważnij klucze, które wyciekły lub nie są używane. Każda osoba tworzy własne klucze w sekcji Moje konto.',
    'while_you_move_off_another_system_an_app_can_ask_for_th_c182528e' => 'Podczas migracji z innego systemu aplikacja może zlecić sprawdzenie e-maila i hasła osoby, której jeszcze nie ma w Cbox ID, w starym punkcie końcowym logowania. Przetestuj go przed zatwierdzeniem. Zaakceptowana osoba zostanie utworzona tutaj i nie będzie już odsyłana do starego systemu. Gdy jednak ten punkt końcowy nie działa, osoby jeszcze nieprzeniesione nie mogą się zalogować.',
    'the_audit_events_your_app_sends_about_each_organization_a385fa1d' => 'Zdarzenia audytu wysyłane przez Twoją aplikację dla każdej obsługiwanej organizacji: kto, co i kiedy zrobił w produkcie. Są przechowywane osobno dla organizacji w łańcuchu skrótów i pokazywane jej administratorom. Użyj tej funkcji, gdy organizacja poprosi o dziennik audytu swojego konta. Zdefiniuj schematy, aby zachować spójność zdarzeń.',
    'no_future_lease_can_open_this_secret_revocation_is_imme_5b330536' => 'Żadne przyszłe uprawnienie czasowe nie pozwoli odczytać tego sekretu. Unieważnienie jest natychmiastowe i trwałe.',
    'no_live_agents_revoked_and_expired_keys_stay_listed_for_8dd5437a' => 'Brak aktywnych agentów. Unieważnione i wygasłe klucze pozostają na liście jako zapis historyczny.',
    'no_permissions_it_identifies_its_holder_and_nothing_mor_80cf422c' => 'Brak uprawnień — jedynie identyfikuje posiadacza',
    'nothing_changes_for_anybody_until_this_is_on_test_a_sig_9eb3389b' => 'Nic się nie zmieni, dopóki tego nie włączysz. Najpierw przetestuj logowanie.',
    'only_a_hash_is_stored_if_it_is_lost_revoke_it_and_creat_6e39a401' => 'Przechowywany jest tylko skrót. Jeśli zgubisz klucz, unieważnij go i utwórz nowy.',
    'only_the_apps_listed_here_can_lease_this_secret_everyth_3afb49f2' => 'Tylko wymienione aplikacje mogą uzyskać czasowy dostęp do tego sekretu. Wszystkie pozostałe żądania są odrzucane.',
    'every_other_device_holding_a_session_as_you__a01280d4' => 'Sesje na wszystkich pozostałych urządzeniach przestaną działać przy następnym żądaniu. Na tym urządzeniu pozostaniesz zalogowany.',
    'no_members_in_this_organization_yet_nobody_can_sign_in_d0c78702' => 'Ta organizacja nie ma jeszcze członków. Nikt nie może się do niej zalogować, dopóki ktoś nie zostanie zaproszony lub dodany przez aprowizację.',
    'no_password_is_set_here_they_get_a_sign_in_link_by_emai_5e488804' => 'Nie ustawiasz tutaj hasła. Użytkownik otrzyma e-mailem link do logowania i wybierze sposób logowania.',
    'each_step_is_measured_from_live_state_so_the_guide_alwa_e7f5c55e' => 'Każdy krok jest oceniany na podstawie bieżącego stanu, więc przewodnik zawsze pokazuje rzeczywistą sytuację tej organizacji.',
    'copy_the_key_now_and_hand_it_to_the_agent_only_a_hash_i_fb10c803' => 'Skopiuj teraz klucz i przekaż go agentowi. Przechowywany jest tylko skrót, więc klucz jest wyświetlany tylko raz.',
    'the_email_domains_this_organization_owns_each_proved_wi_02a41e13' => 'Domeny e-mail należące do tej organizacji, każda potwierdzona rekordem DNS TXT. Po weryfikacji domeny możesz włączyć wymuszanie SSO, które kieruje wszystkich użytkowników z adresem w tej domenie do firmowego połączenia SSO zamiast logowania hasłem. Zweryfikuj wszystkie domeny używane przez osoby w organizacji, zanim oprzesz logowanie na SSO.',
    'your_app_s_own_access_model_resource_types_like_documen_24105154' => 'Własny model dostępu aplikacji: typy zasobów, takie jak dokumenty i foldery, relacje, takie jak właściciel, edytor i czytelnik, oraz sposób ich dziedziczenia. Osoby mogące przeglądać folder mogą na przykład czytać wszystkie jego dokumenty. Aplikacja zapisuje relacje osób z zasobami i przy każdym żądaniu pyta, czy użytkownik może edytować dokument. Odpowiedź wynika ze schematu.',
    'this_environment_serves_an_mcp_server_the_standard_way_eb9faa22' => 'To środowisko udostępnia obok REST API serwer MCP — standardowy sposób wywoływania narzędzi przez asystentów AI. Wklej adres i klucz zarządzania do Claude Code, Cursor lub innego klienta MCP. Agent będzie mógł robić dokładnie to, na co pozwalają zakresy klucza, z takimi samymi kontrolami i dziennikiem audytu jak w konsoli.',
    'a_key_lets_your_own_scripts_and_integrations_call_an_ap_4edbc37d' => 'Klucz pozwala Twoim skryptom i integracjom wywoływać API aplikacji w Twoim imieniu, bez logowania. Może robić tylko to, co Ty w tej aplikacji: gdy tracisz dostęp, klucz też go traci. Klucz jest wyświetlany tylko raz. Skopiuj go podczas tworzenia i natychmiast unieważnij, jeśli wycieknie lub przestanie być potrzebny.',
    'provisioning_stops_and_the_group_mappings_go_with_it_th_b562bdb6' => 'Aprowizacja zostanie zatrzymana, a mapowania grup usunięte. Utworzeni użytkownicy pozostaną.',
    'provisioning_stops_immediately_and_every_group_mapping_7a323b54' => 'Aprowizacja zostanie natychmiast zatrzymana, a wszystkie mapowania grup usunięte. Tej operacji nie można cofnąć.',
    'provisioning_to_the_downstream_app_stops_immediately_th_6d193c25' => 'Aprowizacja do aplikacji docelowej zostanie natychmiast zatrzymana. Tej operacji nie można cofnąć.',
    'provisioning_to_the_downstream_app_stops_immediately_th_948dd5a5' => 'Aprowizacja do aplikacji docelowej zostanie natychmiast zatrzymana. Utworzeni tam użytkownicy pozostaną.',
    'phone_number_removed_their_other_factors_and_recovery_c_a792580f' => 'Numer telefonu został usunięty. Pozostałe czynniki uwierzytelniania i kody odzyskiwania użytkownika pozostają bez zmian.',
    'people_already_connected_keep_the_scopes_they_agreed_to_f979f289' => 'Już połączeni użytkownicy zachowają zakresy, na które wyrazili zgodę, dopóki nie połączą się ponownie.',
    'origins_updated_the_change_is_live_on_the_next_request_6bb5bfb0' => 'Źródła zostały zaktualizowane. Zmiana zacznie obowiązywać przy następnym żądaniu.',
    'other_systems_may_be_using_this_changing_it_changes_the_41e0f485' => 'Inne systemy mogą z tego korzystać. Zmiana wpłynie na zapisane w nich adresy URL.',
    'people_who_rely_on_this_provider_lose_their_way_in_this_10f27c15' => 'Osoby korzystające z tego dostawcy stracą ten sposób logowania. Tej operacji nie można cofnąć.',
    'project_suspended_its_environments_stay_live_but_no_new_be6ca1ef' => 'Projekt został zawieszony. Jego środowiska nadal działają, ale nie można dodawać nowych do czasu ponownego aktywowania projektu.',
    'role_definition_activated_existing_holders_now_use_thes_381596d2' => 'Definicja roli została aktywowana. Jej obecni posiadacze korzystają teraz z tych uprawnień.',
    'rule_activated_grants_that_would_break_it_are_blocked_f_fb4adf4c' => 'Reguła została aktywowana. Od teraz nadania uprawnień, które by ją naruszały, są blokowane.',
    'schema_saved_events_of_this_action_are_checked_against_8215a899' => 'Schemat został zapisany. Od teraz zdarzenia tej akcji są według niego sprawdzane.',
    'schema_saved_every_check_is_decided_by_it_from_now_on_e54cf8c0' => 'Schemat został zapisany. Od teraz decyduje o wyniku każdej kontroli.',
    'refuse_events_whose_action_has_no_schema_turn_on_once_e_c5af42c9' => 'Odrzucaj zdarzenia, których akcja nie ma schematu. Włącz, gdy każda akcja wysyłana przez aplikację będzie go mieć.',
    'objects_are_written_to_prefix_yyyy_mm_dd_hh_batch_ndjso_5c6035ae' => 'Obiekty są zapisywane w prefix/yyyy/mm/dd/hh/batch.ndjson.gz, po jednym zdarzeniu w wierszu.',
    'only_for_an_s3_compatible_store_such_as_minio_or_cloudf_266ca7ae' => 'Tylko dla magazynu zgodnego z S3, takiego jak MinIO lub Cloudflare R2. Puste pole oznacza użycie punktu końcowego AWS dla regionu.',
    'register_this_as_an_allowed_redirect_uri_at_the_provide_b537b90c' => 'Zarejestruj to u dostawcy jako dozwolony URI przekierowania, dokładnie w pokazanej postaci.',
    'webhooks_sign_out_notices_to_connected_apps_role_update_776577f9' => 'Webhooki, powiadomienia o wylogowaniu do połączonych aplikacji, pobierane z nich aktualizacje ról i e-maile w kolejce są obsługiwane w tle przez procesy kolejki, bez czekania użytkownika. Jeśli żaden proces nie działa, nic nie zostanie wysłane, choć reszta konsoli wygląda poprawnie. Na tej stronie zobaczysz problem.',
    'a_round_where_you_go_through_who_holds_which_role_and_c_617023b9' => 'Przegląd, podczas którego sprawdzasz, kto ma jaką rolę, i potwierdzasz, czy nadal jej potrzebuje. Dostęp gromadzi się niepostrzeżenie: ludzie zmieniają zespoły, zachowując stare uprawnienia. Przegląd pozwala je usunąć. Odebranie dostępu jest stosowane po zamknięciu przeglądu, a cały proces zostaje zapisany dla audytora.',
    'if_the_app_declares_a_different_url_later_this_approval_d8bd0ea4' => 'Jeśli aplikacja później poda inny URL, zatwierdzenie zostanie cofnięte i będzie wymagane ponownie. Zmiana miejsca wysyłania haseł wymaga ponownej zgody. Delegowane logowanie jest rozwiązaniem przejściowym: gdy w starym systemie pozostanie niewiele osób, wyłącz je i wyślij tej grupie wiadomości do resetowania hasła.',
    'lets_your_people_sign_in_with_the_company_account_they_5186cda3' => 'Pozwala użytkownikom logować się istniejącym kontem firmowym, takim jak Microsoft Entra ID, Okta lub Google Workspace, zamiast osobnym hasłem tutaj. Podłącz dostawcę tożsamości raz i potwierdź domeny e-mail. Wszyscy użytkownicy tych domen będą kierowani do dostawcy w celu logowania.',
    'every_person_with_an_identity_in_this_environment_which_f9f26f27' => 'Wszystkie osoby z tożsamością w tym środowisku, niezależnie od organizacji, do których należą. Otwórz osobę, aby zresetować hasło lub drugi składnik, zakończyć jej sesje, wyłączyć konto, zmienić organizacje i role albo trwale usunąć dane w odpowiedzi na żądanie realizacji prawa do usunięcia danych.',
    'paste_the_provider_s_metadata_xml_or_its_metadata_url_a_70d6c8b8' => 'Wklej metadane dostawcy w formacie XML lub ich adres URL, a poniższe pola wypełnią się automatycznie.',
    'paste_this_into_your_identity_provider_with_the_bearer_6f366a6e' => 'Wklej to u dostawcy tożsamości wraz z tokenem bearer z podłączanego katalogu.',
    'point_your_oidc_client_at_these_discovery_exposes_every_81f0fa9a' => 'Skonfiguruj klienta OIDC, używając tych adresów. Mechanizm wykrywania automatycznie udostępnia wszystkie punkty końcowe.',
    'register_an_application_that_uses_this_environment_as_i_8eee8cef' => 'Zarejestruj aplikację, która korzysta z tego środowiska jako dostawcy tożsamości SAML.',
    'register_one_to_let_an_application_sign_its_users_in_wi_e20e6b01' => 'Zarejestruj, aby aplikacja mogła logować użytkowników przy użyciu kont, które już mają w tym środowisku.',
    'only_the_apps_listed_here_get_a_token_everything_else_i_3d600e70' => 'Tylko wymienione tu aplikacje otrzymają token. Wszystkie pozostałe żądania są odrzucane.',
    'no_entitlements_set_for_this_organization_it_runs_on_th_76313cb5' => 'Nie ustawiono uprawnień do funkcji dla tej organizacji. Obowiązują domyślne ustawienia wdrożenia.',
    'organizations_in_the_targeted_environment_as_the_manage_2f2361fb' => 'Organizacje w wybranym środowisku przedstawione jako drzewo zarządzania.',
    'owned_by_this_environment_rather_than_by_an_organizatio_60be3a32' => 'Należy do tego środowiska, a nie do organizacji',
    'platform_operators_administer_environments_across_the_w_e0a9f173' => 'Operatorzy platformy administrują środowiskami w całej instalacji.',
    'platform_wide_usage_across_every_environment_not_only_t_0e12a08a' => 'Użycie całej platformy we wszystkich środowiskach, nie tylko w tym wybranym w konsoli.',
    'how_organization_owners_and_operators_sign_in_to_cbox_i_444d5c8b' => 'Sposób logowania właścicieli i operatorów organizacji do Cbox ID ustawia się w konsoli środowiska platformy.',
    'these_run_in_the_middle_of_an_operation_not_after_it_an_c325ec80' => 'Te punkty rozszerzeń działają w trakcie operacji, a nie po niej, i ich odpowiedź zmienia wynik: Twój endpoint może dodać informacje do tokenu lub odmówić logowania. Mają duże możliwości i leżą bezpośrednio na ścieżce wykonywania operacji — wolny lub niedziałający endpoint odczuje osoba próbująca się zalogować.',
    'your_identity_provider_creates_updates_and_deactivates_2d9dc172' => 'Dostawca tożsamości sam tworzy, aktualizuje i dezaktywuje tutaj osoby za pomocą standardu SCIM. Zatrudnienie lub odejście pracownika odnotowane w systemie kadrowym dociera do aplikacji w ciągu sekund, bez zgłoszeń i pozostawionych kont — co ma szczególne znaczenie przy odejściu.',
    'how_many_organizations_users_single_sign_on_connections_8e80258f' => 'Liczba organizacji, użytkowników, połączeń jednokrotnego logowania, aplikacji i synchronizacji użytkowników w tym środowisku, z odnośnikami do odpowiednich stron. Skróty poniżej rozpoczynają najczęstsze czynności: tworzenie organizacji, użytkownika, połączenia jednokrotnego logowania lub aplikacji.',
    'a_role_is_a_job_title_your_apps_understand_editor_suppo_73cd7eac' => 'Rola to funkcja rozumiana przez aplikacje, np. „Redaktor” lub „Pracownik wsparcia”. Tutaj ustalasz, kto ma daną rolę, a każda aplikacja sama określa jej uprawnienia. Role towarzyszą osobie we wszystkich połączonych aplikacjach, więc dostęp nadajesz i odbierasz w jednym miejscu.',
    'mirrors_every_audit_log_entry_into_your_security_team_s_b980f702' => 'Przesyła kopię każdego wpisu dziennika audytu do narzędzi zespołu bezpieczeństwa, takich jak SIEM, w chwili jego zapisu. Skonfiguruj miejsce docelowe, aby dochodzenia zaczynały się w używanych już narzędziach, bez prośby o eksport. Dostarczenie odbywa się co najmniej raz, więc mogą pojawiać się duplikaty.',
    'an_organization_appears_here_the_moment_somebody_signs__d46ff7af' => 'Organizacja pojawi się tutaj, gdy ktoś się zarejestruje. Możesz też utworzyć ją przyciskiem Nowa organizacja powyżej.',
    'add_the_domain_this_organization_s_people_have_email_ad_e68cad70' => 'Dodaj domenę adresów e-mail osób w tej organizacji, opublikuj rekord TXT i zweryfikuj domenę.',
    'prove_ownership_of_an_email_domain_to_route_your_team_t_bc84ec01' => 'Potwierdź własność domeny e-mail, aby automatycznie kierować zespół do SSO.',
    'prove_the_organization_owns_a_domain_then_route_everyon_3c9f7db4' => 'Potwierdź, że organizacja jest właścicielem domeny, a następnie kieruj wszystkich jej użytkowników do logowania organizacji.',
