    'it_replaces_the_sealed_value_on_rotate_and_is_never_sho_cec701f1' => 'Podczas rotacji zastępuje zaszyfrowaną wartość i nie jest ponownie wyświetlany. Zachowaj własną kopię, jeśli jej potrzebujesz.',
    'replace_the_sealed_value_with_a_new_credential_the_stor_17b46d38' => 'Zastąp zaszyfrowaną wartość nowymi danymi uwierzytelniającymi. Zapisana wartość nigdy nie jest wyświetlana.',
    'sealed_the_moment_you_save_it_and_never_shown_again_kee_db995569' => 'Szyfrowany w chwili zapisania i nigdy więcej nie wyświetlany. Zachowaj własną kopię, jeśli jej potrzebujesz.',
    'stored_sealed_and_never_shown_again_leave_it_empty_to_k_72338e4f' => 'Przechowywany w postaci zaszyfrowanej i nigdy więcej nie wyświetlany. Pozostaw puste, aby zachować obecną wartość.',
    'secret_rotated_and_the_previous_one_has_stopped_working_14aacb17' => 'Sekret został zmieniony, a poprzedni przestał działać. Skopiuj nowy teraz — nie zostanie ponownie wyświetlony.',
    'revoking_is_immediate_and_permanent_no_future_lease_can_27e17e18' => 'Unieważnienie jest natychmiastowe i trwałe. Żadne przyszłe uprawnienie czasowe nie pozwoli odczytać tego sekretu.',
    'metadata_schemas_are_a_subset_of_json_schema_an_object_64eba270' => 'Schematy metadanych stanowią podzbiór JSON Schema: obiekt o właściwościach typu tekst, liczba, liczba całkowita, wartość logiczna lub null, z wyliczeniami oraz ograniczeniami długości, zakresu, wzorca i formatu. Zapisanie zmiany tworzy nową wersję; wcześniej zapisane zdarzenia zachowują wersję, względem której je sprawdzono.',
    'each_pipe_lets_people_connect_their_own_account_at_a_se_ec4853ae' => 'Każde połączenie pozwala użytkownikom podłączyć własne konto w usłudze takiej jak GitHub, Google czy Slack. Tokeny są tutaj przechowywane w postaci zaszyfrowanej i odświeżane. Upoważnione aplikacje proszą o działający token za każdym razem, gdy wywołują usługę w imieniu użytkownika, i same go nie przechowują.',
    'an_admin_support_role_is_a_role_you_grant_to_your_own_p_4b6ac4cb' => 'Rola administracyjna i wsparcia jest nadawana własnym pracownikom, np. zespołom wsparcia lub operacyjnym, w całym środowisku. Obowiązuje w każdej organizacji, a jej administratorzy nie mogą jej zobaczyć, nadać ani odebrać. Własna rola aplikacji nadana w ten sposób obowiązuje tylko w tej aplikacji.',
    'an_environment_is_a_fully_isolated_identity_service_wit_993d6053' => 'Środowisko to w pełni odizolowana usługa tożsamości z własnymi użytkownikami, kluczami, logowaniem i wystawcą. Tutaj widoczne są wszystkie środowiska tej instalacji wraz z obszarem roboczym, do którego należą. Utwórz środowisko, przełącz na nie konsolę i dodaj pierwszą organizację oraz administratora.',
    'a_chain_is_one_organization_s_send_organization_id_f35ed1e5' => 'Łańcuch należy do jednej organizacji: przekaż organization_id.',
    'a_support_session_lasts_at_most_max_minutes_069774e6' => 'Maksymalny czas sesji pomocy technicznej (min): :max.',
    'active_sso_connections' => 'Aktywne połączenia: :active z :total.',
