    'a_phone_with_the_authenticator_app_installed_becomes_th_caef4b54' => 'Telefon z zainstalowaną aplikacją uwierzytelniającą służy do odpowiadania na prośby o zatwierdzenie i powiadamia o logowaniu na Twoje konto. Zarejestruj go raz, skanując kod. Jeśli go zgubisz, natychmiast usuń go tutaj, aby nie mógł niczego zatwierdzać.',
    'an_organization_is_one_signed_up_company_s_home_on_this_b98406a0' => 'Obszar roboczy to miejsce zarejestrowanej firmy w tej instalacji, zawierające jej projekty, środowiska i zespół. Otwórz go, aby przejrzeć produkty i środowiska, albo zawieś: spowoduje to wylogowanie członków i zablokowanie logowania we wszystkich należących do niego środowiskach.',
    'when_an_app_or_an_ai_agent_needs_your_go_ahead_to_act_a_51a99858' => 'Gdy aplikacja lub agent AI potrzebuje zgody na działanie w Twoim imieniu, nie zawsze może o nią poprosić na ekranie przed Tobą — dlatego prosi tutaj. Zatwierdzaj tylko samodzielnie rozpoczęte żądania i sprawdzaj, czy pokazany kod zgadza się z kodem na urządzeniu wysyłającym żądanie.',
