    'looks_up_an_organization_by_name_or_handle_or_a_user_by_d7460886' => 'Wyszukuje organizację po nazwie lub identyfikatorze albo użytkownika po imieniu i nazwisku lub adresie e-mail we wszystkich środowiskach tej instalacji, nie tylko w wybranym w konsoli. Użyj, gdy ktoś prosi o pomoc, a nie wiesz, w którym jest środowisku.',
