    'sent_when_someone_s_account_is_created_leave_it_empty_f_c7c58d7f' => 'Wysyłane przy utworzeniu konta użytkownika. Pozostaw puste, aby użyć wartości domyślnej.',
    'only_for_a_provider_that_does_not_publish_its_signing_k_e4c5eb2d' => 'Tylko dla dostawcy, który nie publikuje kluczy podpisujących (jwks_uri) w dokumencie wykrywania. W pozostałych przypadkach klucze są pobierane stamtąd, także po rotacji. Podaj klucz publiczny PEM. Jest przechowywany w postaci zaszyfrowanej i nie będzie ponownie wyświetlany; pozostaw puste, aby zachować obecny.',
    'some_pairs_of_roles_must_never_sit_with_the_same_person_70e4454a' => 'Niektóre pary ról nigdy nie powinny należeć do tej samej osoby: osoba zlecająca płatność nie powinna jej także zatwierdzać. Określ te pary tutaj. Cbox ID zablokuje nowe nadania naruszające regułę i pokaże osoby, które już mają sprzeczną parę ról.',
    'api_keys_and_tokens_your_apps_and_agents_need_for_other_f9b71876' => 'Klucze API i tokeny potrzebne aplikacjom i agentom do innych usług, przechowywane tutaj w postaci zaszyfrowanej zamiast w konfiguracji każdej aplikacji. Sekret podajesz raz i upoważniasz wybrane aplikacje do jego użycia. Nie zostanie ponownie pokazany — jeśli go utracisz, wymień go.',
