    'each_organization_is_a_company_or_team_using_your_produ_08cdcb7d' => 'Każda organizacja to firma lub zespół korzystający z Twojego produktu, z własnymi członkami, rolami, domenami i jednokrotnym logowaniem. Utwórz osobną organizację dla każdej rejestrującej się firmy. Otwórz ją, aby zarządzać członkami, zaproszeniami i zweryfikowanymi domenami albo ją zawiesić.',
    'cbox_id_posts_a_signed_message_to_your_endpoint_after_s_8dadac57' => 'Cbox ID wysyła podpisaną wiadomość do Twojego endpointu po zdarzeniu, np. dołączeniu członka lub zmianie roli, aby Twoje systemy mogły reagować bez cyklicznego odpytywania. Nieudane dostarczenie jest ponawiane. Dzieje się to po fakcie: endpoint otrzymuje informację, ale nie decyduje o wyniku.',
    'a_schema_says_what_an_action_s_events_must_look_like_wh_d27be344' => 'Schemat określa strukturę zdarzeń danej akcji: wskazywane typy obiektów docelowych i zawartość metadanych. Zdarzenia akcji ze schematem są sprawdzane przy odbiorze. Bez schematu przyjmuje się je w wysłanej postaci, chyba że włączony jest tryb ścisły.',
    'everyone_who_administers_this_organization_the_built_in_69802df4' => 'Wszystkie osoby zarządzające tym obszarem roboczym, ich wbudowane role — Właściciel, Administrator, Deweloper, Członek lub Obserwator — oraz dostępne im środowiska. Zapraszaj e-mailem i każdej osobie udostępniaj tylko środowiska potrzebne do pracy.',
    'let_the_people_who_use_your_apps_connect_their_own_gith_19a2d0ed' => 'Pozwól użytkownikom aplikacji podłączyć własne konta GitHub, Google, Slack lub Salesforce, aby aplikacje mogły wywoływać te API w ich imieniu. Tokeny są tutaj szyfrowane, przechowywane i odświeżane, a czasowy dostęp do nich otrzymują tylko upoważnione aplikacje.',
    'the_invitee_accepts_by_email_nobody_is_added_to_an_orga_04408aaf' => 'Zaproszona osoba akceptuje zaproszenie przez e-mail. Nikt nie jest dodawany do organizacji bez swojej zgody.',
