    'platform_operators_administer_every_organization_and_en_36866fb1' => 'Operatorzy platformy zarządzają wszystkimi obszarami roboczymi i środowiskami tej instalacji, ponad zakresem każdego z nich. Dodawaj operatora tylko dla osoby odpowiedzialnej za samą instalację i zawieś go, gdy przestanie pełnić tę funkcję.',
    'every_organization_in_the_environment_the_console_is_po_0de4eff9' => 'Wszystkie organizacje w środowisku wybranym w konsoli, ułożone w drzewo odsprzedawców, zarządzanych przez nich organizacji i ich podjednostek. Tutaj możesz utworzyć organizację, zawiesić ją lub przenieść pod inną organizację nadrzędną.',
    'sign_ins_tokens_issued_new_users_and_two_factor_enrolme_e9040ee7' => 'Logowania, wydane tokeny, nowi użytkownicy i rejestracje uwierzytelniania dwuskładnikowego, dzień po dniu z ostatnich 30 dni, chyba że w instalacji ustawiono inny okres. Strona pozostaje pusta, dopóki operator instalacji nie skonfiguruje miejsca przechowywania danych analitycznych.',
