    'every_browser_and_device_signed_in_as_you_the_apps_you_ee516093' => 'Wszystkie przeglądarki i urządzenia zalogowane na Twoje konto, aplikacje upoważnione do działania w Twoim imieniu oraz ostatnie logowania i zmiany zabezpieczeń. Jeśli nie rozpoznajesz aktywności, wyloguj daną sesję lub odbierz aplikacji dostęp, a następnie zmień hasło.',
