    'issue_a_fresh_token_the_one_your_identity_provider_hold_c37da34e' => 'Wydaj nowy token. Token obecnie używany przez dostawcę tożsamości natychmiast przestanie działać. Po rotacji od razu skopiuj nowy token do dostawcy tożsamości.',
    'let_your_identity_provider_create_update_and_deactivate_1208087e' => 'Pozwól dostawcy tożsamości samodzielnie tworzyć, aktualizować i dezaktywować tutaj osoby oraz mapować jego grupy na Twoje role.',
    'let_your_provider_create_and_deactivate_people_here_on_7db65233' => 'Pozwól dostawcy samodzielnie tworzyć i dezaktywować użytkowników tutaj, aby odchodząca osoba traciła dostęp wszędzie bez zgłoszenia do pomocy.',
    'light_mode_muted_text_on_the_background_is_ratio_1_it_n_7f4cfb27' => 'Tryb jasny: przygaszony tekst na tle ma kontrast :ratio:1 — wymagane jest 3:1.',
