    'list_at_least_one_origin_a_key_presentable_from_nowhere_71e6ca50' => 'Podaj co najmniej jedno źródło — klucz, którego nie można nigdzie użyć, jest jak klucz unieważniony. Zamiast tego unieważnij go.',
