    'each_link_opens_part1_in_that_environment_s_console_5f38b7b2' => 'Każdy link otwiera stronę „:part1” w konsoli danego środowiska.',
    'unchanged_by_anything_here_so_nothing_to_update_in_part_75ac8c0d' => 'Nic na tej stronie nie zmienia tego URI, więc nie trzeba niczego aktualizować w :part1.',
    'risk_score_part1_part2_recorded_under_part3_part4_ae0bca2b' => 'Ocena ryzyka: :part1 (:part2) · tryb w chwili zapisu: :part3 :part4',
    'what_a_person_may_do_in_an_organization_assi_3fc83055' => 'Co dana osoba może robić w organizacji. Przydzielane poszczególnym członkom; aplikacja sprawdza bieżące uprawnienia przed chronionymi operacjami.',
    'what_an_organization_has_paid_for_set_by_bil_fc59c3a4' => 'Z czego organizacja może korzystać w ramach planu lub jawnie przyznanych praw. Zarządzane w Billing; aplikacja sprawdza bieżące prawa dostępu do usług.',
    'use_2_to_16_lowercase_letters_or_digits_star_cda1343d' => 'Użyj od 2 do 16 małych liter lub cyfr, zaczynając od litery, a następnie _live lub _test — na przykład acme_live.',
    'use_an_absolute_url_with_a_host_and_no_fragm_134d4387' => 'Użyj bezwzględnego adresu URL z hostem i bez fragmentu, maksymalnie 255 znaków — na przykład https://api.example.com.',
    'we_could_not_send_the_text_message_check_the_ad67f38a' => 'Nie udało się wysłać wiadomości SMS. Sprawdź numer i spróbuj ponownie.',
    'we_fetch_a_short_lived_token_from_the_app_be_7b50ead6' => 'Przed każdą partią pobieramy z aplikacji krótkotrwały token. Wymagane są adres URL tokenu i identyfikator klienta.',
    'whether_a_feature_is_switched_on_for_someone_631c0d5f' => 'Czy funkcja jest dla kogoś włączona. Stopniowe wdrażanie, a nie kontrola dostępu — nigdy nie zabezpieczaj tym danych.',
    'who_may_do_what_to_which_record_your_app_wri_ca6c6d61' => 'Kto może zrobić co z którym rekordem. Aplikacja zapisuje relacje i żąda sprawdzenia przy każdym żądaniu.',
    'organization_created_but_the_owner_could_not_21800822' => 'Utworzono organizację, ale nie udało się wysłać linku właścicielowi. Poproś go o użycie opcji „Nie pamiętam hasła”.',
    'you_re_signed_in_you_don_t_belong_to_an_orga_67d0efb9' => 'Jesteś zalogowany. Nie należysz tu jeszcze do żadnej organizacji — konto i ustawienia bezpieczeństwa pozostają wyłącznie Twoje.',
    'when_an_app_or_agent_needs_your_go_ahead_to_act_as_you_3a85a2a9' => 'Gdy aplikacja lub agent potrzebuje zgody na działanie w Twoim imieniu, prosi o nią tutaj. Zatwierdzaj tylko żądania, które samodzielnie rozpoczęto.',
    'you_need_credentials_from_your_own_account_with_the_pro_6556573b' => 'Potrzebujesz danych uwierzytelniających z własnego konta u dostawcy, zwykle identyfikatora i sekretu klienta. Apple zamiast sekretu wydaje klucz podpisujący.',
    'you_stop_being_able_to_sign_in_with_it_if_it_66b928b9' => 'Tracisz możliwość logowania tą metodą. Jeśli jest jedyną, zmiana zostanie odrzucona. Najpierw ustaw hasło lub dodaj klucz dostępu.',
    'you_will_no_longer_be_able_to_sign_in_with_a_a575bedf' => 'Nie będzie można logować się kodem z SMS-a. Aplikacja uwierzytelniająca, klucze dostępu i kody odzyskiwania pozostają bez zmian.',
    'your_endpoint_is_called_in_the_middle_of_an_operation_a_ab67a6b0' => 'Twój endpoint jest wywoływany w trakcie operacji, a odpowiedź zmienia wynik: może dodać dane do tokenu lub odmówić logowania.',
    '_created_d8cbb77e' => ' · utworzono: ',
    '_expires_886eec4c' => ' · wygasa: ',
    'already_exists_here_4acf85c5' => 'ma już tutaj konto',
    'down_908aec45' => 'niedostępny',
    'including_yours_1124fe26' => 'w tym twoja',
    'see_your_apps_83cc472a' => 'zobacz swoje aplikacje',
    'the_full_quickstart_dd59dd4d' => 'pełną instrukcję szybkiego startu',
    'a_management_key_acts_in_its_own_environment_only_expor_d9ba3890' => 'Klucz zarządzania działa tylko we własnym środowisku. Wyeksportuj szablon aplikacji (GET /apps/{id}/blueprint) i zarejestruj go kluczem drugiego środowiska (POST /apps z `blueprint`).',
    'add_the_domain_and_publish_the_txt_record_it_shows_or_s_ddb14174' => 'Dodaj domenę i opublikuj wskazany rekord TXT — albo wyślij administratorowi IT organizacji link do portalu administracyjnego, aby zrobił to sam.',
    'asked_before_every_rule_a_deny_entry_blocks_an_allow_en_e80b3f61' => 'Sprawdzane przed każdą regułą. Wpis odmowy blokuje; wpis zezwolenia pomija wszystkie reguły, również wbudowane. Jeśli oba dotyczą tej samej próby, odmowa ma pierwszeństwo.',
    'attach_this_to_the_iam_user_whose_access_key_the_stream_7659ba28' => 'Dołącz to do użytkownika IAM, którego klucza dostępu używa strumień: może zapisywać obiekty pod prefiksem i nic więcej — bez odczytu, listowania ani usuwania.',
    'choose_scim_if_your_provider_pushes_to_us_google_worksp_99b715bb' => 'Wybierz SCIM, jeśli dostawca wysyła dane do nas, Google Workspace lub Entra, jeśli mamy je pobierać, albo system kadrowy — Workday, BambooHR, Rippling, HiBob lub Personio — aby użytkownicy byli dodawani w dniu rozpoczęcia pracy.',
    'from_the_next_attempt_blocks_refuse_sign_ins_and_sign_u_e89996c3' => 'Od następnej próby blokady odrzucają logowania i rejestracje w tym środowisku, a dodatkowe kontrole wymagają weryfikacji. Błędna reguła może zablokować prawdziwych użytkowników.',
    'give_it_the_endpoint_or_bucket_and_the_credential_it_ex_4cf81bb7' => 'Podaj punkt końcowy lub zasobnik i oczekiwane dane uwierzytelniające; dla odbiornika HTTP pozostaw sekret pusty, aby wygenerować klucz HMAC.',
    'let_an_organization_sign_in_with_okta_entra_id_or_googl_cf114dfb' => 'Pozwól organizacji logować się przez Okta, Entra ID lub Google Workspace — albo wyślij administratorowi link do portalu administracyjnego, aby skonfigurował to sam.',
    'selected_permissions_count' => 'Wybrane uprawnienia: :count',
    'sso_required_organization' => 'Firmowe SSO jest wymagane dla organizacji :organization. Wszystkie inne metody logowania są blokowane, dopóki ten wymóg nie zostanie zmieniony w sekcji „:policy”.',
    'sso_required_environment' => 'Firmowe SSO jest wymagane w tym środowisku. Wszystkie inne metody logowania są blokowane, dopóki ten wymóg nie zostanie zmieniony w sekcji „:policy”.',
    'someone_who_part1_is_never_sent_their_password_is_the_o_6e557319' => 'Jeśli ktoś :part1, jego logowanie nigdy nie trafia do starego systemu. Obowiązuje hasło z Cbox ID, a stary system nie ma wpływu na uwierzytelnianie.',
    'if_that_endpoint_is_part1_people_who_have_not_migrated_18fc0415' => 'Jeśli ten punkt końcowy jest :part1, osoby jeszcze nieprzeniesione nie mogą się zalogować. Osoby już przeniesione nie są dotknięte problemem.',
    'every_session_in_this_organization_ends_part1_part2_b33262fc' => 'Każda sesja w tej organizacji zostanie zakończona — :part1 :part2.',
    'the_same_code_step_by_step_with_sign_out_part1_part2_4d2f071e' => 'Ten sam kod krok po kroku, z wylogowaniem — zobacz :part1 :part2.',
    'the_newest_entries_on_part1_s_trail_dac97d7d' => 'Najnowsze wpisy w dzienniku audytu organizacji :part1.',
    '_part1_refuses_the_sign_in_unless_this_matches_exactly_8d9cdd26' => ':part1 odmówi logowania, jeśli wartość nie będzie dokładnie zgodna. Jest zarezerwowana dla tej konfiguracji, więc możesz wkleić ją teraz w :part2, a zapisać tutaj później.',
    '_part1_sessions_passkeys_and_second_factors_identity_pr_1ab27bf9' => ':part1 — sesje, klucze dostępu, drugie składniki, profile dostawców tożsamości, dane katalogowe, wydane tokeny, przypisania ról i historia audytu zostają zachowane. Osobę można ponownie aktywować.',
    '_part1_things_worth_doing_roughly_in_this_order_each_on_b3e154c4' => 'Zalecane kroki: :part1, mniej więcej w tej kolejności. Każdy zaznacza się automatycznie, gdy zostanie faktycznie wykonany; nie trzeba niczego oznaczać ręcznie.',
    '_part1_this_console_is_not_signed_in_to_with_them_admin_a3d216ed' => ':part1 Te metody nie służą do logowania do tej konsoli. Administratorzy logują się przez Cbox ID pod adresem :part2, używając jego metod logowania.',
    'a_management_key_for_one_agent_it_can_do_only_what_its_e35f0a5f' => 'Klucz zarządzania dla jednego agenta. Pozwala tylko na działania dozwolone przez jego zakresy, a wskazane czynności czekają na Twoje zatwierdzenie na telefonie lub tutaj: :part1.',
    'a_part1_is_one_product_s_idp_it_holds_isolated_part2_pa_c2f6b974' => ':part1 to dostawca tożsamości jednego produktu, rozliczany według własnego planu. Zawiera odizolowane :part2 :part3 — produkcyjne i testowe — każde z własnymi użytkownikami, kluczami i logowaniem.',
    'an_organization_key_reaches_the_organization_itself_pro_0257779c' => 'Klucz obszaru roboczego daje dostęp do samego obszaru: projektów, środowisk, zespołu i kluczy, ale nie do wnętrza środowiska. Utwórz go na głównym poziomie platformy w sekcji :part1 :part2 :part3.',
    'applications_that_trust_this_environment_as_their_saml_0e2642cf' => 'Aplikacje ufające temu środowisku jako dostawcy tożsamości SAML. Aby umożliwić logowanie istniejącymi kontami z innych usług, użyj :part1 :part2.',
    'approvals_cover_the_management_api_s_actions_these_scop_3eade41d' => 'Zatwierdzenia obejmują akcje API zarządzania. Te zakresy obsługują endpointy, które jeszcze nie są akcjami, więc wykonują się bez pytania o zgodę: :part1 :part2.',
    'link_an_app_with_the_same_owner_as_the_api_tokens_for_t_0a546071' => 'Połącz aplikację mającą tego samego właściciela co API. Tokeny dla tego API zawierają role i uprawnienia połączonej aplikacji, dlatego musi ona należeć do tego samego właściciela.',
    'not_configured_radar_can_still_block_but_cannot_ask_a_p_0a163809' => 'Nie skonfigurowano — Radar nadal może blokować, ale nie może prosić o potwierdzenie, że użytkownik jest człowiekiem. Przy oznaczonej rejestracji zamiast tego potwierdza się adres e-mail.',
    'pick_where_the_trail_goes_splunk_elastic_graylog_cef_or_e69f3c8f' => 'Wybierz miejsce docelowe ścieżki audytu — Splunk, Elastic, Graylog, CEF lub dowolny odbiornik JSON, Datadog albo własny zasobnik Amazon S3 lub Google Cloud Storage.',
    'puts_the_keys_of_the_feature_flags_that_are_on_for_the_70599dc3' => 'Umieszcza klucze flag funkcji włączonych dla osoby w organizacji, do której się zalogowała, w tokenie dostępu, tokenie ID i UserInfo jako pole `feature_flags`.',
    'puts_everything_userinfo_answers_for_the_app_s_scopes_e_db47369d' => 'Umieszcza w tokenie ID wszystko, co UserInfo zwraca dla zakresów aplikacji (e-mail, imię i nazwisko, role, uprawnienia, organizacje), dzięki czemu aplikacja może pominąć wywołanie UserInfo przy logowaniu. Tylko dla aplikacji, która przy wylogowaniu wysyła `id_token_hint` metodą POST albo nie wysyła go wcale: token w adresie URL trafia do dzienników dostępu.',
    'puts_the_person_s_roles_on_the_id_token_under_the_name_1df84dc6' => 'Umieszcza ROLE osoby w tokenie ID pod nazwą `groups` — tego szukają Kubernetes, Grafana, Vault i większość starszych usług SaaS. W tej konsoli nie ma obiektu o nazwie grupa: utwórz rolę o nazwie oczekiwanej przez aplikację, a pojawi się tutaj.',
    'register_an_app_so_your_people_can_sign_in_to_it_with_t_9fcc62a6' => 'Zarejestruj aplikację, aby użytkownicy mogli logować się do niej kontem, które mają tutaj. Ten krok sprawia, że zaczynają rzeczywiście korzystać z Cbox ID.',
    'that_favicon_cannot_be_used_send_the_image_itself_as_a_96450fb1' => 'Tej ikony witryny nie można użyć. Wyślij sam obraz jako base64 data: URI (data:image/png;base64,…). Zdalne adresy URL obrazów nie są akceptowane: każdy odwiedzający pobiera obraz ze strony logowania, a zewnętrzny URL ujawniłby jego serwerowi, kim są odwiedzający.',
    'that_logo_cannot_be_used_send_the_image_itself_as_a_bas_ae6a22d5' => 'Tego logo nie można użyć. Wyślij sam obraz jako base64 data: URI (data:image/png;base64,…). Zdalne adresy URL obrazów nie są akceptowane: każdy odwiedzający pobiera obraz ze strony logowania, a zewnętrzny URL ujawniłby jego serwerowi, kim są odwiedzający.',
    'the_address_is_a_tor_exit_node_a_vpn_or_an_open_proxy_t_f7fc0d8a' => 'Adres jest węzłem wyjściowym Tor, VPN lub otwartym proxy. Tor jest rozpoznawany z lokalnej listy węzłów wyjściowych; VPN i proxy wymagają usługi analizy IP, która je zgłasza.',
    'the_button_disappears_from_every_sign_in_page_in_this_e_c817a046' => 'Przycisk znika ze wszystkich stron logowania w tym środowisku, które go dziedziczą. Dane uwierzytelniające pozostają zapisane, więc możesz włączyć go ponownie.',
    'the_button_disappears_from_this_organization_s_sign_in_88a1cc4f' => 'Przycisk znika ze strony logowania tej organizacji — przycisk środowiska go nie zastępuje. Dane uwierzytelniające pozostają zapisane, więc możesz włączyć go ponownie.',
    'the_console_is_pointed_at_this_environment_and_every_pa_4d2a0145' => 'Konsola przełącza się na to środowisko i każda odtąd otwierana strona odczytuje je zamiast obecnego. W żadnym z nich nic się nie zmienia.',
    'the_sign_in_page_your_people_see_is_yours_not_ours_logo_7573e3bf' => 'Strona logowania ma identyfikację Twojej organizacji: logo, kolory i teksty. Zmiany są widoczne na żywo w podglądzie i stosowane na hostowanej stronie logowania tej organizacji.',
    'this_credential_needs_a_person_s_approval_for_this_acti_6e7eed81' => 'Te dane uwierzytelniające wymagają zatwierdzenia tej akcji przez człowieka, ale nie ma zapisanej osoby, która mogłaby to zrobić. Uruchom akcję z konsoli albo wydaj klucz w konsoli, aby właściciel mógł zatwierdzić.',
    'this_environment_falls_back_to_its_default_domain_every_201d6a2d' => 'To środowisko wraca do domeny domyślnej. Każdy klient przypisany do obecnego wystawcy, adresu wykrywania lub adresu JWKS przestaje działać do czasu zmiany konfiguracji.',
    'we_could_not_send_the_email_right_now_this_deployment_c_03e046b9' => 'Nie udało się teraz wysłać e-maila — instalacja nie może połączyć się z serwerem poczty. Spróbuj później; administrator może też potwierdzić adres poleceniem `php artisan cbox-id:users:confirm-email`.',
    'your_sign_in_page_carries_your_logo_and_colours_people_76d3ce22' => 'Twoja strona logowania ma Twoje logo i kolory. Ludzie wpisują na niej hasło — powinna wyglądać jak Twoja, nie nasza.',
    'creating_an_app_issues_a_client_secret_shown_2840959a' => 'Utworzenie aplikacji wydaje sekret klienta, wyświetlany tylko raz na następnym ekranie — służy do logowania jako ta aplikacja do czasu rotacji.',
    'registering_an_app_issues_a_client_secret_sh_631bb9f1' => 'Rejestracja aplikacji tworzy sekret klienta, wyświetlany tylko raz na następnym ekranie. Umożliwia on uwierzytelnianie jako ta aplikacja do czasu wymiany sekretu.',
    'there_is_no_other_environment_in_this_projec_bfd62f34' => 'W tym projekcie nie ma innego środowiska, którym zarządzasz. Dodaj je do projektu lub poproś o dostęp, a pojawi się tutaj.',
    'this_app_belongs_to_an_organization_and_an_o_5487ac51' => 'Ta aplikacja należy do organizacji, a organizacja istnieje tylko w jednym środowisku. Pobierz jej szablon i zarejestruj w drugim środowisku w organizacji, do której tam należy.',
    'this_app_registered_itself_so_it_is_not_one__ec7cea33' => 'Ta aplikacja zarejestrowała się sama, więc nie jest własną aplikacją tego środowiska. Może zarejestrować się w ten sam sposób w drugim środowisku.',
    'this_app_signs_in_with_its_own_keys_and_each_a40a0c9b' => 'Ta aplikacja loguje się własnymi kluczami i każde środowisko powinno mieć własne. Pobierz jej szablon i zarejestruj w drugim środowisku z zestawem kluczy tego środowiska.',
    'app_keys_unavailable_organization_switch' => 'Aplikacja, która cię tu skierowała, nie udostępnia kluczy API dla organizacji :organization. Spróbuj innej organizacji lub skontaktuj się z pomocą techniczną aplikacji.',
    'app_keys_unavailable_organization' => 'Aplikacja, która cię tu skierowała, nie udostępnia kluczy API dla organizacji :organization. Skontaktuj się z pomocą techniczną aplikacji.',
    'app_keys_unavailable_switch' => 'Aplikacja, która cię tu skierowała, nie udostępnia kluczy API. Spróbuj innej organizacji lub skontaktuj się z pomocą techniczną aplikacji.',
    'app_keys_unavailable' => 'Aplikacja, która cię tu skierowała, nie udostępnia kluczy API. Skontaktuj się z pomocą techniczną aplikacji.',
    'connect_once_at_the_platform_root_instead_of_once_per_e_df000287' => 'Połącz raz na głównym poziomie platformy zamiast osobno dla każdego środowiska. Agent zalogowany w Twoim imieniu ma dostęp do obszaru roboczego, wszystkich jego środowisk, którymi zarządzasz, i Twojego konta. Narzędzie środowiskowe przyjmuje argument :part1 :part2, a API REST nagłówek :part3, wskazujące miejsce działania. Agent może robić to, co Ty, w granicach udzielonej zgody, a każda krytyczna czynność czeka na zatwierdzenie na Twoim urządzeniu.',
    'each_organization_gives_them_one_part1_what_they_may_ad_69f922a2' => 'Każda organizacja przydziela osobie jeden element typu :part1, określający uprawnienia administracyjne, oraz dowolną liczbę ról typu :part2, określających możliwości w aplikacjach.',
    'environment_part1_created_add_part2_from_the_environmen_9b25a836' => 'Utworzono środowisko „:part1”. Dodaj :part2 w ustawieniach domen środowiska, aby zweryfikować domenę przez DNS. Niezweryfikowana domena nie może być wystawcą środowiska.',
    'environments_nest_under_a_project_and_a_project_under_a_a7f5aa8e' => 'Środowiska należą do projektu, a projekt do obszaru typu :part1 :part2 :part3. Zacznij tam, aby zobaczyć wszystkie jego zasoby. Dwa rodzaje wpisów nie mają obszaru roboczego: :part4 to środowisko samej instalacji, gdzie znajdują się operatorzy i członkowie obszarów roboczych; środowisko oznaczone jako :part5 :part6 nie ma projektu, więc nie jest rozliczane i żaden obszar roboczy nie ma do niego dostępu. Żaden przypadek nie jest błędem do naprawienia na tym ekranie; nie można tu również zmienić ich przypisania.',
    'every_way_people_sign_in_to_part1_whether_it_is_on_and_4dda4364' => 'Wszystkie metody logowania do :part1, ich stan i miejsce zmiany. Organizacje mogą zaostrzać te zasady: :part2 :part3.',
    'no_applications_match_part1_try_a_different_entity_id_386ed821' => 'Żadna aplikacja nie pasuje do „:part1”. Spróbuj innego identyfikatora encji.',
    'no_organizations_match_part1_try_a_different_name_or_ha_72ccc404' => 'Żadna organizacja nie pasuje do „:part1”. Spróbuj innej nazwy lub identyfikatora.',
    'your_endpoint_verifies_the_part1_header_on_each_request_b7ca1bb8' => 'Twój punkt końcowy używa tego sekretu do weryfikacji nagłówka :part1 w każdym żądaniu.',
    'ask_an_owner_of_the_organization_to_give_you_access_to__74d808e8' => 'Poproś właściciela obszaru roboczego o dostęp do :part1.',
    'hand_it_to_part1_over_a_channel_you_trust_we_never_stor_205e825e' => 'Przekaż je użytkownikowi :part1 zaufanym kanałem. Nigdy nie przechowujemy go w czytelnej postaci.',
    'in_the_order_people_see_them_turning_one_of_the_environ_390888a5' => 'W kolejności widocznej dla użytkowników. Wyłączenie tutaj dostawcy środowiska usuwa tylko przycisk z tej strony; nie blokuje logowania nim gdzie indziej. Aby Twój dostawca był jedyną metodą, wymagaj SSO w :part1 :part2.',
    'its_part1_can_no_longer_sign_in_to_this_organization_an_9a6e499c' => 'Osoby objęte zmianą (:part1) nie mogą już logować się do tej organizacji, a zależne od niej aplikacje przestają je uwierzytelniać. Organizacje podrzędne nie zostają zawieszone. Możesz ponownie aktywować tę organizację tutaj.',
    'keys_start_with_it_so_a_key_found_in_a_log_names_this_a_8a69e3c2' => 'Klucze zaczynają się od tego prefiksu, dzięki czemu klucz znaleziony w logu wskazuje aplikację: :part1 :part2. Użyj 2–16 małych liter lub cyfr, a następnie :part3 lub :part4 :part5, unikatowo w tym środowisku. Ustawienie prefiksu włącza klucze; wyczyszczenie blokuje tworzenie nowych, ale istniejące działają do unieważnienia.',
    'nobody_in_this_organization_has_created_a_key_for_one_o_d0240315' => 'Nikt w tej organizacji nie utworzył klucza dla jej aplikacji. Użytkownicy tworzą własne w sekcji Moje konto dla aplikacji, która w Ustawieniach włączy klucze API członków: :part1.',
    'paste_the_whole_json_key_file_of_a_service_account_gran_6f4e93cd' => 'Wklej cały plik JSON klucza konta usługi z rolą roles/storage.objectCreator dla zasobnika. Jest przechowywany w postaci zaszyfrowanej i nie będzie ponownie pokazany. :part1',
