    'add_this_dns_part1_record_at_your_domain_then_verify_it_3d494578' => 'Dodaj ten rekord DNS :part1 w swojej domenie, a następnie go zweryfikuj. Potwierdzi to, że kontrolujesz domenę :part2.',
