    'roles_held_across_the_whole_environment_in_every_organi_eb64cef7' => 'Role obowiązujące w całym środowisku, w każdej organizacji, nawet gdy osoba nie należy do żadnej. Organizacje nigdy ich nie widzą. :part1 :part2',
    'sign_in_to_one_of_your_apps_as_part1_to_see_what_they_s_1c96b645' => 'Zaloguj się do aplikacji jako :part1, aby zobaczyć to, co ta osoba. Aplikacja wie, że to Ty, a dziennik audytu organizacji zapisuje, kto to zrobił, kiedy i dlaczego.',
    'someone_who_signs_in_and_is_part1_has_their_email_and_p_07a25128' => 'Gdy osoba próbuje się zalogować i ma stan :part1, jej e-mail i hasło są wysyłane do tego endpointu. Jeśli endpoint zaakceptuje logowanie, osoba zostaje utworzona tutaj, a dane nie są już tam wysyłane.',
    'stuck_on_one_of_these_every_page_in_the_console_has_a_p_2aa4622e' => 'Potrzebujesz pomocy z którymś krokiem? Każda strona konsoli ma ikonę :part1 :part2 :part3 obok tytułu, z krótkim wyjaśnieniem i linkiem do pełnego poradnika.',
    'suspension_is_the_only_lever_here_and_it_is_reversible__9f87c506' => 'Jedyną dostępną tu operacją jest odwracalne zawieszenie. Ten ekran nie usuwa ani nie czyści trwale obszarów roboczych. Instalacja zawiera też środowiska bez obszaru roboczego: główne środowisko platformy i nieprzypisane pozostałości. Oba typy są opisane w :part1 :part2.',
