    'text_message_codes_to_part1_stop_working_their_authenti_81d0cd27' => 'Kody SMS dla :part1 przestają działać. Aplikacja uwierzytelniająca, klucze dostępu i kody odzyskiwania pozostają bez zmian. Jeśli telefon był jedynym drugim składnikiem, konto będzie chronione tylko hasłem do ponownej rejestracji.',
    'that_is_everything_on_the_list_from_here_the_console_is_d3be406f' => 'To wszystko z listy. Od teraz konsola służy głównie do regularnego sprawdzania działania usługi. Warto wyrobić sobie nawyk odwiedzania tych dwóch obszarów: :part1 :part2 :part3 oraz :part4 :part5 :part6.',
    'the_email_domains_your_organizations_have_claimed_a_ver_97773852' => 'Domeny e-mail zgłoszone przez Twoje organizacje. Zweryfikowana domena kieruje każdą osobę z adresem w tej domenie do połączenia organizacji: :part1 :part2. Każdą domenę weryfikuje się na stronie jej organizacji.',
