    'these_are_the_buttons_on_part1_how_every_organization_o_ca549807' => 'To przyciski na stronie :part1. Właściciele i operatorzy obszarów roboczych logują się przez nie do Cbox ID, a tym samym do konsoli każdego środowiska, której administratorzy mają konta Cbox ID. Zarejestruj u każdego dostawcy wyświetlany URI przekierowania; korzysta on z hosta :part2 :part3.',
